// Booking slot rules: the ONE place that decides which times can be booked.
//
// Used in two places:
//  - the n8n workflow (copied into its Code nodes by tools/build_n8n.mjs), which checks Google Calendar
//    and returns only the free slots, and re-checks a slot before booking it;
//  - the booking pop-up (src/ui/booking.js), only as a fallback while n8n isn't connected.
//
// Change the hours here, run `node tools/build_n8n.mjs`, and re-import n8n/rework-review-booking.json.
// Keep this file free of imports and browser/Node-only APIs: it must run inside an n8n Code node.

const RULES = {
  hostOffsetHours: 8,          // Philippine time, UTC+8, no daylight saving
  days: [1, 2, 3, 4, 5],       // days a window STARTS on (0 = Sunday): Monday to Friday
  start: '08:00',              // first start time, Philippine time
  end: '02:00',                // window ends at this time; earlier than start means the next day (Fri 8:00 am to Sat 2:00 am)
  slotMinutes: 30,             // meeting length, and the step between start times
  minNoticeHours: 12,          // no bookings sooner than this
  daysAhead: 28,               // how far ahead people can book
};

const MIN = 60e3;

function toMinutes(hhmm) {
  const [h, m] = hhmm.split(':').map(Number);
  return h * 60 + m;
}

/** Every bookable start time (ms since epoch, UTC) from now, before checking the calendar. */
function candidateSlots(nowMs, rules = RULES) {
  const off = rules.hostOffsetHours * 60 * MIN;
  const startMin = toMinutes(rules.start);
  let endMin = toMinutes(rules.end);
  if (endMin <= startMin) endMin += 24 * 60;
  const earliest = nowMs + rules.minNoticeHours * 60 * MIN;
  const latest = nowMs + rules.daysAhead * 24 * 60 * MIN;

  // Host-local midnight of "today", as a UTC timestamp. Start one day back so a window that began
  // yesterday evening and runs past midnight is still included.
  const hostNow = new Date(nowMs + off);
  const todayMidnight = Date.UTC(hostNow.getUTCFullYear(), hostNow.getUTCMonth(), hostNow.getUTCDate()) - off;

  const out = [];
  for (let i = -1; i <= rules.daysAhead + 1; i++) {
    const dayStart = todayMidnight + i * 24 * 60 * MIN;
    const weekday = new Date(dayStart + off).getUTCDay();
    if (!rules.days.includes(weekday)) continue;
    for (let m = startMin; m + rules.slotMinutes <= endMin; m += rules.slotMinutes) {
      const t = dayStart + m * MIN;
      if (t >= earliest && t <= latest) out.push(t);
    }
  }
  return out;
}

/** Free start times: candidates that don't overlap any busy period ({start, end} ISO strings). */
function freeSlots(nowMs, busy = [], rules = RULES) {
  const periods = busy
    .map((b) => [Date.parse(b.start), Date.parse(b.end)])
    .filter(([s, e]) => Number.isFinite(s) && Number.isFinite(e));
  const len = rules.slotMinutes * MIN;
  return candidateSlots(nowMs, rules).filter((t) => !periods.some(([s, e]) => t < e && t + len > s));
}

/** True if this exact start time (ISO string) is one the rules allow. Does not check the calendar. */
function isAllowedSlot(iso, nowMs, rules = RULES) {
  const t = Date.parse(iso);
  if (!Number.isFinite(t)) return false;
  return candidateSlots(nowMs, rules).includes(t);
}

// Change or cancel a booking, and the reminder sweep. Run inside the n8n booking workflow (tools/build_n8n.mjs
// copies this file in with slots.js and check.js; import lines are dropped there). 20 Nov 2026, Jeff: automated.
//
// How it fits together
//  - Every booking's Google Calendar event carries private details (extendedProperties.private, visible only on
//    Jeff's calendar): a random key, the visitor's name, email and time zone, the start the workflow knows about,
//    how many times it was changed, and which reminders went out.
//  - The invite and reminders link to https://rework-rescue.vercel.app/#booking=KEY. The pop-up sends that key to
//    the rr-manage webhook to look the booking up, move it (same event, same Meet link) or cancel it.
//  - Every 10 minutes the workflow reads the calendar and the bookings sheet (sweepReminders): it sends reminders
//    that are due for the event's CURRENT time, notices when Jeff moved or cancelled a review in Google Calendar,
//    or the visitor declined the invite, and keeps the sheet in step.
//
// Keep this file free of browser/Node-only APIs: it must run inside an n8n Code node.

const CHANGE_RULES = {
  maxChanges: 2,            // a visitor can move one booking twice; after that, "reply to the invite"
  // New times follow the normal booking rules in slots.js (12 hours' notice, up to 28 days ahead).
  // Moving or cancelling is possible until the review starts.
};
const SITE_URL = 'https://rework-rescue.vercel.app/';
const EVENT_TITLE = 'Free review with Jeff (Rework Rescue)';
const KEY_RE = /^[A-Za-z0-9]{24,64}$/;
const LIST_DAYS = 60; // how far ahead the sweep reads the calendar (bookings go 28 days ahead)

const HOUR_MS = 3600e3;
const MINUTE_MS = 60e3;

/** The visitor's private link. A #fragment, so the key never reaches a server log or another site. */
const changeLink = (key) => `${SITE_URL}#booking=${key}`;

/** Fallback key if the n8n Crypto node didn't supply one (it normally does). */
function newKey(rand = Math.random) {
  const abc = 'abcdefghijklmnopqrstuvwxyz0123456789';
  let k = '';
  for (let i = 0; i < 32; i++) k += abc[Math.floor(rand() * abc.length) % abc.length];
  return k;
}

/** What a new booking keeps on its calendar event. Google needs every value as a string. */
function bookingProps({ key, name, email, tz, start, nowMs }) {
  return {
    rr: '1', rrKey: key, rrName: name, rrEmail: email, rrTz: tz || '', rrStart: new Date(Date.parse(start)).toISOString(),
    rrSet: String(nowMs), rrChanges: '0', rrDay: '', rrHour: '', rrState: '',
  };
}

const iso = (ms) => new Date(ms).toISOString();
const props = (ev) => ({ ...((ev && ev.extendedProperties && ev.extendedProperties.private) || {}) });
const sheetTimes = (ms) => ({ 'Review time (PH)': fmtSheet(ms), 'Review time (UTC)': iso(ms) });
const host = (ms) => `${fmtHost(ms)} Philippine time`;

// ---------------------------------------------------------------- rr-manage webhook

/**
 * First check of a change request, before Google is asked anything.
 * body: { key, action: 'look' | 'move' | 'cancel', slot? (ISO, for move) }
 */
function checkChange(body, nowMs, rules = RULES) {
  const b = body && typeof body === 'object' ? body : {};
  const key = String(b.key ?? '').trim();
  const action = String(b.action ?? '');
  if (!KEY_RE.test(key)) return { ok: false, status: 404, code: 'not_found' };
  if (!['look', 'move', 'cancel'].includes(action)) return { ok: false, status: 400, code: 'action' };
  if (action !== 'move') return { ok: true, key, action };
  const slot = String(b.slot ?? '').slice(0, 40);
  if (!isAllowedSlot(slot, nowMs, rules)) return { ok: false, status: 400, code: 'slot' };
  const startMs = Date.parse(slot);
  return { ok: true, key, action, start: iso(startMs), end: iso(startMs + rules.slotMinutes * MINUTE_MS) };
}

/**
 * Decide what to do, given the request (checkChange) and Google's answer to
 * events?privateExtendedProperty=rrKey=KEY. Returns what to answer, and for move/cancel what to change.
 */
function decideChange(req, list, nowMs, rules = CHANGE_RULES) {
  const no = (status, code) => ({ ok: false, status, code, respond: { ok: false, error: code } });
  const items = (list && Array.isArray(list.items)) ? list.items : [];
  const ev = items.find((e) => e && e.status !== 'cancelled' && props(e).rrKey === req.key && e.start && e.start.dateTime);
  if (!ev) return no(404, 'not_found');
  const p = props(ev);
  const startMs = Date.parse(ev.start.dateTime);
  const endMs = Date.parse((ev.end && ev.end.dateTime) || '') || startMs + 30 * MINUTE_MS;
  if (!(startMs > nowMs)) return no(410, 'started');
  const changes = Number(p.rrChanges) || 0;
  const left = Math.max(0, rules.maxChanges - changes);
  const name = p.rrName || '';
  const first = name.split(' ')[0] || '';
  const base = { eventId: ev.id, link: ev.htmlLink || '', email: p.rrEmail || '', from: iso(startMs) };

  if (req.action === 'look') {
    return { ok: true, status: 200, action: 'look', respond: { ok: true, start: iso(startMs), end: iso(endMs), name: first, changesLeft: left } };
  }

  const who = [`Name: ${name}`, `Email: ${p.rrEmail || ''}`, p.rrTz ? `Visitor's time zone: ${p.rrTz}` : ''].filter(Boolean);

  if (req.action === 'move') {
    if (left <= 0) return no(409, 'no_changes_left');
    const toMs = Date.parse(req.start);
    if (toMs === startMs) return no(400, 'same_time');
    return {
      ok: true, status: 200, action: 'move', ...base, to: iso(toMs),
      patch: {
        start: { dateTime: req.start }, end: { dateTime: req.end },
        extendedProperties: { private: { ...p, rrStart: iso(toMs), rrSet: String(nowMs), rrChanges: String(changes + 1), rrDay: '', rrHour: '', rrState: '' } },
      },
      sheet: { 'Calendar link': ev.htmlLink || '', ...sheetTimes(toMs), Status: 'Rescheduled' },
      notify: {
        subject: `Review moved: ${name}, now ${host(toMs)}`,
        text: [`${name} moved their free review using the change link.`, '', `From: ${host(startMs)}`, `To:   ${host(toMs)}`, '',
          ...who, '', 'The calendar event and their invite are updated. The Meet link stays the same.',
          `Changes used: ${changes + 1} of ${rules.maxChanges}.`].join('\n'),
      },
      respond: { ok: true, action: 'move', start: iso(toMs), end: req.end, changesLeft: left - 1 },
    };
  }

  // cancel
  return {
    ok: true, status: 200, action: 'cancel', ...base, to: null,
    sheet: { 'Calendar link': ev.htmlLink || '', Status: 'Cancelled' },
    notify: {
      subject: `Review cancelled: ${name}, ${host(startMs)}`,
      text: [`${name} cancelled their free review using the change link.`, '', `Was: ${host(startMs)}`, '', ...who, '',
        'The calendar event is cancelled and Google has told them. Their email can book again.'].join('\n'),
    },
    respond: { ok: true, action: 'cancel' },
  };
}

// ---------------------------------------------------------------- 10-minute sweep: reminders and keeping in step

/** "2026-11-24 09:00" (or with seconds) in Philippine time, as the sheet shows it. */
function parsePh(v) {
  const m = String(v ?? '').match(/(\d{4})-(\d{2})-(\d{2})[ T,]+(\d{1,2}):(\d{2})/);
  if (!m) return NaN;
  return Date.UTC(+m[1], +m[2] - 1, +m[3], +m[4] - 8, +m[5]);
}
function rowStart(row) {
  const utc = String(row['Review time (UTC)'] ?? '');
  if (/Z$|[+-]\d\d:\d\d$/.test(utc) && Number.isFinite(Date.parse(utc))) return Date.parse(utc);
  return parsePh(row['Review time (PH)']);
}

/**
 * @param {object} list   Google events.list for now .. now + LIST_DAYS (singleEvents), ALL events on the calendar
 * @param {object[]} rows the bookings sheet rows (header names as keys)
 * @param {number} nowMs
 * @returns {{items: object[], moves: {email, from, to}[]}}
 *   items: one per thing to do, with any of
 *     eventId + patch  (update the event's private details; done BEFORE the email so a reminder is never sent twice)
 *     email            ({to, subject, text})
 *     sheet            (row update, matched on 'Calendar link')
 *   moves: for the remembered bookings (to = null: cancelled)
 */
function sweepReminders(list, rows, nowMs) {
  if (!list || !Array.isArray(list.items)) throw new Error('Google Calendar list missing: ' + JSON.stringify(list).slice(0, 300));
  const complete = !list.nextPageToken;
  const events = list.items.filter((e) => e && e.status !== 'cancelled');
  const links = new Set(events.map((e) => e.htmlLink).filter(Boolean));
  const rowByLink = new Map((rows || []).filter((r) => r && r['Calendar link']).map((r) => [r['Calendar link'], r]));
  const items = [];
  const moves = [];

  for (const ev of events) {
    let p = props(ev);
    const row = rowByLink.get(ev.htmlLink);
    const tagged = p.rr === '1';
    // Bookings made before 20 Nov have no private details: adopt them from their sheet row (no change link).
    const legacy = !tagged && ev.summary === EVENT_TITLE && !!row;
    if (!tagged && !legacy) continue;
    if (!ev.start || !ev.start.dateTime) continue;
    const startMs = Date.parse(ev.start.dateTime);
    if (!(startMs > nowMs)) continue;
    const start = iso(startMs);
    let changed = false;
    let sheet = null;
    if (legacy) {
      const guest0 = (ev.attendees || []).find((a) => a && !a.organizer && !a.self) || {};
      const bookedAt = parsePh(row['Booked at (PH)']);
      p = {
        rr: '1', rrKey: '', rrName: row.Name || guest0.displayName || '', rrEmail: String(row.Email || guest0.email || '').toLowerCase(),
        rrTz: row['Visitor time zone'] || '', rrStart: start, rrSet: String(Number.isFinite(bookedAt) ? bookedAt : 0),
        rrChanges: '0', rrDay: '', rrHour: '', rrState: '',
      };
      changed = true;
    }

    const guest = (ev.attendees || []).find((a) => a && String(a.email || '').toLowerCase() === p.rrEmail);
    if (guest && guest.responseStatus === 'declined') {
      if (p.rrState !== 'declined') items.push({ eventId: ev.id, patch: { extendedProperties: { private: { ...p, rrState: 'declined' } } }, sheet: { 'Calendar link': ev.htmlLink, Status: 'Declined' } });
      else if (changed) items.push({ eventId: ev.id, patch: { extendedProperties: { private: p } } });
      continue; // no reminders for a declined invite
    }
    if (p.rrState === 'declined') { p.rrState = ''; changed = true; sheet = { 'Calendar link': ev.htmlLink, Status: 'Booked' }; }

    // Moved in Google Calendar (by Jeff, or by a change the sweep hasn't seen): follow the new time.
    if (Date.parse(p.rrStart) !== startMs) {
      moves.push({ email: p.rrEmail, from: p.rrStart, to: start });
      p = { ...p, rrStart: start, rrSet: String(nowMs) };
      changed = true;
      sheet = { 'Calendar link': ev.htmlLink, ...sheetTimes(startMs), Status: 'Rescheduled' };
    }

    // Reminders for the event's current time. The sweep runs every 10 minutes.
    let email = null;
    const ahead = startMs - nowMs;
    const data = { name: p.rrName, email: p.rrEmail, tz: p.rrTz, start, meet: ev.hangoutLink || '', key: p.rrKey };
    if (p.rrHour !== start && ahead <= HOUR_MS && ahead > 10 * MINUTE_MS) {
      email = reminderEmail('hour', data);
      p = { ...p, rrHour: start, rrDay: start };
    } else if (p.rrDay !== start && ahead <= 24 * HOUR_MS && ahead > 2 * HOUR_MS && startMs - (Number(p.rrSet) || 0) >= 24 * HOUR_MS + 5 * MINUTE_MS) {
      // Skipped when the booking (or the last move) was made less than a day ahead, as before.
      email = reminderEmail('day', data);
      p = { ...p, rrDay: start };
    }
    if (email && !p.rrEmail) email = null;
    if (changed || email) items.push({ eventId: ev.id, patch: { extendedProperties: { private: p } }, ...(email ? { email } : {}), ...(sheet ? { sheet } : {}) });
  }

  // Cancelled in Google Calendar: a sheet row still "Booked" or "Rescheduled" whose event is gone.
  // Only when Google's list is complete, so a short or failed read never marks real bookings as cancelled.
  if (complete) {
    for (const row of rows || []) {
      const link = row && row['Calendar link'];
      const t = row ? rowStart(row) : NaN;
      if (!link || !['Booked', 'Rescheduled'].includes(String(row.Status || '').trim())) continue;
      if (!(t > nowMs && t < nowMs + (LIST_DAYS - 1) * 24 * HOUR_MS) || links.has(link)) continue;
      items.push({ sheet: { 'Calendar link': link, Status: 'Cancelled' } });
      moves.push({ email: String(row.Email || '').toLowerCase(), from: iso(t), to: null });
    }
  }
  return { items, moves };
}

// Booking request checks, run inside the n8n workflow before anything touches the calendar.
// The pop-up validates too, but the webhook is public, so these checks are the real gate.
// Copied into n8n by tools/build_n8n.mjs together with slots.js and manage.js (the import lines are dropped there).

const BOOKING_LIMITS = {
  name: 80, email: 254, company: 120, process: 400, summary: 2000, tz: 64,
  perEmailUpcoming: 1,     // one upcoming review per email address
  perDay: 6,               // new bookings accepted in any 24 hours, across everyone
};

// The opening of the calendar invite the visitor receives. Update the link if the site moves to its own domain.
const INVITE_PREP = [
  'Bring one report or check your team keeps redoing. Live example: https://rework-rescue.vercel.app/#samples',
  'No files or prep needed. Please leave out anything confidential.',
  '',
  'Your details',
];

// 20 Nov 2026: each booking gets a private link to change or cancel it (src/booking/manage.js).
const CHANGE_LINE = 'Need a different time? Change or cancel here:';

const clean = (v, max) => String(v ?? '').replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/g, '').replace(/[ \t]+/g, ' ').trim().slice(0, max);
const EMAIL = /^[^\s@<>()[\]\\,;:"]+@[^\s@<>()[\]\\,;:"]+\.[^\s@<>()[\]\\,;:"]{2,}$/;

const fmtHost = (ms) => new Intl.DateTimeFormat('en-US', {
  timeZone: 'Asia/Manila', weekday: 'long', month: 'long', day: 'numeric', hour: 'numeric', minute: '2-digit',
}).format(new Date(ms));

/**
 * @param {object} body     the JSON the pop-up sent
 * @param {number} nowMs
 * @param {{email:string, slot:string, at:number}[]} history  bookings this workflow accepted before
 * @param {object} [rules]
 * @param {string} [key]  the change-link key (from the n8n Crypto node); a fallback key is made if it's missing
 * @returns {{ok:true, booking:object, event:object, notify:object} | {ok:false, status:number, code:string}}
 */
function checkBooking(body, nowMs, history = [], rules = RULES, key = '') {
  const b = body && typeof body === 'object' ? body : {};
  // Honeypot: a hidden field people never fill in. Pretend it worked so bots don't learn anything.
  if (clean(b.website, 200)) return { ok: false, status: 200, code: 'ok' };

  const name = clean(b.name, BOOKING_LIMITS.name + 1);
  const email = clean(b.email, BOOKING_LIMITS.email + 1).toLowerCase();
  const company = clean(b.company, BOOKING_LIMITS.company);
  const process = clean(b.process, BOOKING_LIMITS.process);
  const summary = String(b.summary ?? '').replace(/\r/g, '').trim().slice(0, BOOKING_LIMITS.summary);
  const tz = clean(b.tz, BOOKING_LIMITS.tz);
  const slot = clean(b.slot, 40);

  if (!name || name.length > BOOKING_LIMITS.name) return { ok: false, status: 400, code: 'name' };
  if (!EMAIL.test(email) || email.length > BOOKING_LIMITS.email) return { ok: false, status: 400, code: 'email' };
  if (!isAllowedSlot(slot, nowMs, rules)) return { ok: false, status: 400, code: 'slot' };

  const startMs = Date.parse(slot);
  const endMs = startMs + rules.slotMinutes * 60e3;
  const upcoming = history.filter((h) => h.email === email && Date.parse(h.slot) > nowMs);
  if (upcoming.length >= BOOKING_LIMITS.perEmailUpcoming) return { ok: false, status: 429, code: 'already_booked' };
  if (history.filter((h) => nowMs - h.at < 24 * 3600e3).length >= BOOKING_LIMITS.perDay) return { ok: false, status: 429, code: 'busy' };

  const start = new Date(startMs).toISOString();
  const end = new Date(endMs).toISOString();
  const whenHost = `${fmtHost(startMs)} Philippine time`;
  const changeKey = KEY_RE.test(String(key)) ? String(key) : newKey();
  const footer = '\nBooked through the Rework Rescue website.';
  const resultLine = summary ? `\nFind Your Rework result:\n${summary}` : '';

  // Invite: what the visitor sees. No time zone line; Google Calendar already shows their local time.
  const inviteLines = [
    `Name: ${name}`, `Email: ${email}`, company ? `Company: ${company}` : '',
    process ? `Report or process: ${process}` : '', resultLine, footer,
  ].filter(Boolean);

  // Notification: what Jeff sees. Keeps the visitor's time zone.
  const notifyLines = [
    `Name: ${name}`, `Email: ${email}`, company ? `Company: ${company}` : '',
    process ? `Report or process: ${process}` : '', tz ? `Visitor's time zone: ${tz}` : '',
    resultLine, footer,
  ].filter(Boolean);

  return {
    ok: true,
    booking: { name, email, company, process, summary, tz, start, end, key: changeKey },
    event: {
      summary: EVENT_TITLE,
      description: [...INVITE_PREP.slice(0, 2), `${CHANGE_LINE} ${changeLink(changeKey)}`, ...INVITE_PREP.slice(2), ...inviteLines].join('\n'),
      start: { dateTime: start },
      end: { dateTime: end },
      attendees: [{ email, displayName: name }],
      conferenceData: { createRequest: { requestId: `rr-${startMs}-${Math.random().toString(36).slice(2, 10)}`, conferenceSolutionKey: { type: 'hangoutsMeet' } } },
      reminders: { useDefault: true },
      // Private to Jeff's calendar: the change-link key and what the reminders need. Guests never see these.
      extendedProperties: { private: bookingProps({ key: changeKey, name, email, tz, start, nowMs }) },
    },
    notify: {
      subject: `New review booked: ${name}${company ? ` (${company})` : ''}, ${whenHost}`,
      text: [`New free review booked for ${whenHost}.`, '', ...notifyLines, '', 'The calendar invite with the Meet link has been sent to them.'].join('\n'),
    },
  };
}

/**
 * Clear remembered bookings so an email can book again (Jeff's reset link; doesn't touch the calendar or sheet).
 * `email` is one address (any case), or 'all' to clear the whole list.
 * @returns {{history:object[], removed:number}}
 */
function forgetBooking(history, email) {
  const list = history || [];
  const target = String(email ?? '').trim().toLowerCase();
  if (!target) return { history: list, removed: 0 };
  const kept = target === 'all' ? [] : list.filter((h) => h.email !== target);
  return { history: kept, removed: list.length - kept.length };
}

/**
 * Keep the remembered bookings in step after a change: `to` is the new start (ISO), or null when cancelled.
 * Only the entry for that email and old start changes.
 */
function moveBooking(history, { email, from, to }) {
  const target = String(email ?? '').trim().toLowerCase();
  const fromMs = Date.parse(from);
  const same = (h) => h.email === target && Date.parse(h.slot) === fromMs;
  const list = history || [];
  return to ? list.map((h) => (same(h) ? { ...h, slot: to } : h)) : list.filter((h) => !same(h));
}

/** Bookings worth remembering for the limits: drop entries more than a day old whose slot has passed. */
function pruneHistory(history, nowMs) {
  return (history || []).filter((h) => Date.parse(h.slot) > nowMs || nowMs - h.at < 24 * 3600e3);
}

// Google Sheet log: one row per booking. Create a sheet whose first row has exactly these headers.
const SHEET_COLUMNS = [
  'Booked at (PH)', 'Review time (PH)', 'Review time (UTC)', 'Name', 'Email', 'Company',
  'Report or process', 'Visitor time zone', 'Find Your Rework result', 'Meet link', 'Calendar link', 'Status',
];

const fmtSheet = (ms) => new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Asia/Manila', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false,
}).format(new Date(ms)).replace(',', '');

/** The sheet row for a booking that went through. Status starts as "Booked" for Jeff to update by hand. */
function sheetRow(booking, { meet = '', eventLink = '', nowMs = Date.now() } = {}) {
  // A leading = + - @ would make Sheets treat a visitor's text as a formula; prefix those with an apostrophe.
  const safe = (v) => { const s = String(v ?? ''); return /^[=+\-@]/.test(s) ? `'${s}` : s; };
  const values = [
    fmtSheet(nowMs), fmtSheet(Date.parse(booking.start)), booking.start, booking.name, booking.email, booking.company,
    booking.process, booking.tz, booking.summary, meet, eventLink, 'Booked',
  ];
  return Object.fromEntries(SHEET_COLUMNS.map((c, i) => [c, i < 3 ? values[i] : safe(values[i])]));
}

// ---------------------------------------------------------------- Reminder emails to the visitor
// Sent by the workflow 1 day and 1 hour before the review, in the visitor's own time zone.
const SITE_EXAMPLES = 'https://rework-rescue.vercel.app/#samples';

function visitorTime(ms, tz) {
  const opts = { weekday: 'long', month: 'long', day: 'numeric', hour: 'numeric', minute: '2-digit', timeZoneName: 'short' };
  try { return new Intl.DateTimeFormat('en-US', { ...opts, timeZone: tz || 'Asia/Manila' }).format(new Date(ms)); }
  catch { return new Intl.DateTimeFormat('en-US', { ...opts, timeZone: 'Asia/Manila' }).format(new Date(ms)); }
}

/**
 * The reminder emails, in the visitor's own time zone. kind: 'day' (1 day before) or 'hour' (1 hour before).
 * When the booking is sent by src/booking/manage.js (sweepReminders), which decides when each one is due.
 * key: the change-link key; without one (bookings made before 20 Nov) the email says to reply instead.
 */
function reminderEmail(kind, { name = '', email = '', tz = '', start, meet = '', key = '' }) {
  const startMs = Date.parse(start);
  const when = visitorTime(startMs, tz);
  const first = String(name || '').split(' ')[0] || 'there';
  const join = meet ? `Join with Google Meet: ${meet}` : 'The Google Meet link is in your calendar invite.';
  const sign = ['Jeff Herson Vida', 'Rework Rescue · Less rework. More real work.'];
  const link = KEY_RE.test(String(key)) ? changeLink(key) : '';
  if (kind === 'day') {
    return {
      to: email,
      subject: 'Reminder: your free review is tomorrow',
      text: [
        `Hi ${first},`, '',
        'A quick reminder of your free 30-minute review with me tomorrow:', when, join, '',
        `Before the call, have one report, check or workflow in mind that your team keeps redoing, like the examples on my site: ${SITE_EXAMPLES}`,
        'No preparation or files needed, and please leave out anything confidential.', '',
        link ? `${CHANGE_LINE} ${link}` : 'Need to change the time? Just reply to this email.', '', ...sign,
      ].join('\n'),
    };
  }
  return {
    to: email,
    subject: 'Starting in an hour: your free review',
    text: [
      `Hi ${first},`, '', `Your free review starts in an hour: ${when}.`, join, '',
      link ? `Can't make it? Change or cancel here: ${link}` : "Can't make it? Just reply to this email.", '',
      'See you soon,', ...sign,
    ].join('\n'),
  };
}

// ---- workflow step
const cal = (($input.first().json.calendars || {}).primary) || {};
if (cal.errors && cal.errors.length) throw new Error('Google Calendar could not be read: ' + JSON.stringify(cal.errors));
const slots = freeSlots(Date.now(), cal.busy || []).map((t) => new Date(t).toISOString());
return [{ json: { slots, minutes: RULES.slotMinutes } }];

// Booking slot rules: the ONE place that decides which times can be booked.
//
// Used in two places:
//  - the n8n workflow (copied into its Code nodes by tools/build_n8n.mjs), which checks Google Calendar
//    and returns only the free slots, and re-checks a slot before booking it;
//  - the booking pop-up (src/ui/booking.js), only as a fallback while n8n isn't connected.
//
// Change the hours here, run `node tools/build_n8n.mjs`, and re-import n8n/rework-review-booking.json.
// Keep this file free of imports and browser/Node-only APIs: it must run inside an n8n Code node.

const RULES = {
  hostOffsetHours: 8,          // Philippine time, UTC+8, no daylight saving
  days: [1, 2, 3, 4, 5],       // days a window STARTS on (0 = Sunday): Monday to Friday
  start: '08:00',              // first start time, Philippine time
  end: '02:00',                // window ends at this time; earlier than start means the next day (Fri 8:00 am to Sat 2:00 am)
  slotMinutes: 30,             // meeting length, and the step between start times
  minNoticeHours: 12,          // no bookings sooner than this
  daysAhead: 28,               // how far ahead people can book
};

const MIN = 60e3;

function toMinutes(hhmm) {
  const [h, m] = hhmm.split(':').map(Number);
  return h * 60 + m;
}

/** Every bookable start time (ms since epoch, UTC) from now, before checking the calendar. */
function candidateSlots(nowMs, rules = RULES) {
  const off = rules.hostOffsetHours * 60 * MIN;
  const startMin = toMinutes(rules.start);
  let endMin = toMinutes(rules.end);
  if (endMin <= startMin) endMin += 24 * 60;
  const earliest = nowMs + rules.minNoticeHours * 60 * MIN;
  const latest = nowMs + rules.daysAhead * 24 * 60 * MIN;

  // Host-local midnight of "today", as a UTC timestamp. Start one day back so a window that began
  // yesterday evening and runs past midnight is still included.
  const hostNow = new Date(nowMs + off);
  const todayMidnight = Date.UTC(hostNow.getUTCFullYear(), hostNow.getUTCMonth(), hostNow.getUTCDate()) - off;

  const out = [];
  for (let i = -1; i <= rules.daysAhead + 1; i++) {
    const dayStart = todayMidnight + i * 24 * 60 * MIN;
    const weekday = new Date(dayStart + off).getUTCDay();
    if (!rules.days.includes(weekday)) continue;
    for (let m = startMin; m + rules.slotMinutes <= endMin; m += rules.slotMinutes) {
      const t = dayStart + m * MIN;
      if (t >= earliest && t <= latest) out.push(t);
    }
  }
  return out;
}

/** Free start times: candidates that don't overlap any busy period ({start, end} ISO strings). */
function freeSlots(nowMs, busy = [], rules = RULES) {
  const periods = busy
    .map((b) => [Date.parse(b.start), Date.parse(b.end)])
    .filter(([s, e]) => Number.isFinite(s) && Number.isFinite(e));
  const len = rules.slotMinutes * MIN;
  return candidateSlots(nowMs, rules).filter((t) => !periods.some(([s, e]) => t < e && t + len > s));
}

/** True if this exact start time (ISO string) is one the rules allow. Does not check the calendar. */
function isAllowedSlot(iso, nowMs, rules = RULES) {
  const t = Date.parse(iso);
  if (!Number.isFinite(t)) return false;
  return candidateSlots(nowMs, rules).includes(t);
}

// Change or cancel a booking, and the reminder sweep. Run inside the n8n booking workflow (tools/build_n8n.mjs
// copies this file in with slots.js and check.js; import lines are dropped there). 20 Nov 2026, Jeff: automated.
//
// How it fits together
//  - Every booking's Google Calendar event carries private details (extendedProperties.private, visible only on
//    Jeff's calendar): a random key, the visitor's name, email and time zone, the start the workflow knows about,
//    how many times it was changed, and which reminders went out.
//  - The invite and reminders link to https://rework-rescue.vercel.app/#booking=KEY. The pop-up sends that key to
//    the rr-manage webhook to look the booking up, move it (same event, same Meet link) or cancel it.
//  - Every 10 minutes the workflow reads the calendar and the bookings sheet (sweepReminders): it sends reminders
//    that are due for the event's CURRENT time, notices when Jeff moved or cancelled a review in Google Calendar,
//    or the visitor declined the invite, and keeps the sheet in step.
//
// Keep this file free of browser/Node-only APIs: it must run inside an n8n Code node.

const CHANGE_RULES = {
  maxChanges: 2,            // a visitor can move one booking twice; after that, "reply to the invite"
  // New times follow the normal booking rules in slots.js (12 hours' notice, up to 28 days ahead).
  // Moving or cancelling is possible until the review starts.
};
const SITE_URL = 'https://rework-rescue.vercel.app/';
const EVENT_TITLE = 'Free review with Jeff (Rework Rescue)';
const KEY_RE = /^[A-Za-z0-9]{24,64}$/;
const LIST_DAYS = 60; // how far ahead the sweep reads the calendar (bookings go 28 days ahead)

const HOUR_MS = 3600e3;
const MINUTE_MS = 60e3;

/** The visitor's private link. A #fragment, so the key never reaches a server log or another site. */
const changeLink = (key) => `${SITE_URL}#booking=${key}`;

/** Fallback key if the n8n Crypto node didn't supply one (it normally does). */
function newKey(rand = Math.random) {
  const abc = 'abcdefghijklmnopqrstuvwxyz0123456789';
  let k = '';
  for (let i = 0; i < 32; i++) k += abc[Math.floor(rand() * abc.length) % abc.length];
  return k;
}

/** What a new booking keeps on its calendar event. Google needs every value as a string. */
function bookingProps({ key, name, email, tz, start, nowMs }) {
  return {
    rr: '1', rrKey: key, rrName: name, rrEmail: email, rrTz: tz || '', rrStart: new Date(Date.parse(start)).toISOString(),
    rrSet: String(nowMs), rrChanges: '0', rrDay: '', rrHour: '', rrState: '',
  };
}

const iso = (ms) => new Date(ms).toISOString();
const props = (ev) => ({ ...((ev && ev.extendedProperties && ev.extendedProperties.private) || {}) });
const sheetTimes = (ms) => ({ 'Review time (PH)': fmtSheet(ms), 'Review time (UTC)': iso(ms) });
const host = (ms) => `${fmtHost(ms)} Philippine time`;

// ---------------------------------------------------------------- rr-manage webhook

/**
 * First check of a change request, before Google is asked anything.
 * body: { key, action: 'look' | 'move' | 'cancel', slot? (ISO, for move) }
 */
function checkChange(body, nowMs, rules = RULES) {
  const b = body && typeof body === 'object' ? body : {};
  const key = String(b.key ?? '').trim();
  const action = String(b.action ?? '');
  if (!KEY_RE.test(key)) return { ok: false, status: 404, code: 'not_found' };
  if (!['look', 'move', 'cancel'].includes(action)) return { ok: false, status: 400, code: 'action' };
  if (action !== 'move') return { ok: true, key, action };
  const slot = String(b.slot ?? '').slice(0, 40);
  if (!isAllowedSlot(slot, nowMs, rules)) return { ok: false, status: 400, code: 'slot' };
  const startMs = Date.parse(slot);
  return { ok: true, key, action, start: iso(startMs), end: iso(startMs + rules.slotMinutes * MINUTE_MS) };
}

/**
 * Decide what to do, given the request (checkChange) and Google's answer to
 * events?privateExtendedProperty=rrKey=KEY. Returns what to answer, and for move/cancel what to change.
 */
function decideChange(req, list, nowMs, rules = CHANGE_RULES) {
  const no = (status, code) => ({ ok: false, status, code, respond: { ok: false, error: code } });
  const items = (list && Array.isArray(list.items)) ? list.items : [];
  const ev = items.find((e) => e && e.status !== 'cancelled' && props(e).rrKey === req.key && e.start && e.start.dateTime);
  if (!ev) return no(404, 'not_found');
  const p = props(ev);
  const startMs = Date.parse(ev.start.dateTime);
  const endMs = Date.parse((ev.end && ev.end.dateTime) || '') || startMs + 30 * MINUTE_MS;
  if (!(startMs > nowMs)) return no(410, 'started');
  const changes = Number(p.rrChanges) || 0;
  const left = Math.max(0, rules.maxChanges - changes);
  const name = p.rrName || '';
  const first = name.split(' ')[0] || '';
  const base = { eventId: ev.id, link: ev.htmlLink || '', email: p.rrEmail || '', from: iso(startMs) };

  if (req.action === 'look') {
    return { ok: true, status: 200, action: 'look', respond: { ok: true, start: iso(startMs), end: iso(endMs), name: first, changesLeft: left } };
  }

  const who = [`Name: ${name}`, `Email: ${p.rrEmail || ''}`, p.rrTz ? `Visitor's time zone: ${p.rrTz}` : ''].filter(Boolean);

  if (req.action === 'move') {
    if (left <= 0) return no(409, 'no_changes_left');
    const toMs = Date.parse(req.start);
    if (toMs === startMs) return no(400, 'same_time');
    return {
      ok: true, status: 200, action: 'move', ...base, to: iso(toMs),
      patch: {
        start: { dateTime: req.start }, end: { dateTime: req.end },
        extendedProperties: { private: { ...p, rrStart: iso(toMs), rrSet: String(nowMs), rrChanges: String(changes + 1), rrDay: '', rrHour: '', rrState: '' } },
      },
      sheet: { 'Calendar link': ev.htmlLink || '', ...sheetTimes(toMs), Status: 'Rescheduled' },
      notify: {
        subject: `Review moved: ${name}, now ${host(toMs)}`,
        text: [`${name} moved their free review using the change link.`, '', `From: ${host(startMs)}`, `To:   ${host(toMs)}`, '',
          ...who, '', 'The calendar event and their invite are updated. The Meet link stays the same.',
          `Changes used: ${changes + 1} of ${rules.maxChanges}.`].join('\n'),
      },
      respond: { ok: true, action: 'move', start: iso(toMs), end: req.end, changesLeft: left - 1 },
    };
  }

  // cancel
  return {
    ok: true, status: 200, action: 'cancel', ...base, to: null,
    sheet: { 'Calendar link': ev.htmlLink || '', Status: 'Cancelled' },
    notify: {
      subject: `Review cancelled: ${name}, ${host(startMs)}`,
      text: [`${name} cancelled their free review using the change link.`, '', `Was: ${host(startMs)}`, '', ...who, '',
        'The calendar event is cancelled and Google has told them. Their email can book again.'].join('\n'),
    },
    respond: { ok: true, action: 'cancel' },
  };
}

// ---------------------------------------------------------------- 10-minute sweep: reminders and keeping in step

/** "2026-11-24 09:00" (or with seconds) in Philippine time, as the sheet shows it. */
function parsePh(v) {
  const m = String(v ?? '').match(/(\d{4})-(\d{2})-(\d{2})[ T,]+(\d{1,2}):(\d{2})/);
  if (!m) return NaN;
  return Date.UTC(+m[1], +m[2] - 1, +m[3], +m[4] - 8, +m[5]);
}
function rowStart(row) {
  const utc = String(row['Review time (UTC)'] ?? '');
  if (/Z$|[+-]\d\d:\d\d$/.test(utc) && Number.isFinite(Date.parse(utc))) return Date.parse(utc);
  return parsePh(row['Review time (PH)']);
}

/**
 * @param {object} list   Google events.list for now .. now + LIST_DAYS (singleEvents), ALL events on the calendar
 * @param {object[]} rows the bookings sheet rows (header names as keys)
 * @param {number} nowMs
 * @returns {{items: object[], moves: {email, from, to}[]}}
 *   items: one per thing to do, with any of
 *     eventId + patch  (update the event's private details; done BEFORE the email so a reminder is never sent twice)
 *     email            ({to, subject, text})
 *     sheet            (row update, matched on 'Calendar link')
 *   moves: for the remembered bookings (to = null: cancelled)
 */
function sweepReminders(list, rows, nowMs) {
  if (!list || !Array.isArray(list.items)) throw new Error('Google Calendar list missing: ' + JSON.stringify(list).slice(0, 300));
  const complete = !list.nextPageToken;
  const events = list.items.filter((e) => e && e.status !== 'cancelled');
  const links = new Set(events.map((e) => e.htmlLink).filter(Boolean));
  const rowByLink = new Map((rows || []).filter((r) => r && r['Calendar link']).map((r) => [r['Calendar link'], r]));
  const items = [];
  const moves = [];

  for (const ev of events) {
    let p = props(ev);
    const row = rowByLink.get(ev.htmlLink);
    const tagged = p.rr === '1';
    // Bookings made before 20 Nov have no private details: adopt them from their sheet row (no change link).
    const legacy = !tagged && ev.summary === EVENT_TITLE && !!row;
    if (!tagged && !legacy) continue;
    if (!ev.start || !ev.start.dateTime) continue;
    const startMs = Date.parse(ev.start.dateTime);
    if (!(startMs > nowMs)) continue;
    const start = iso(startMs);
    let changed = false;
    let sheet = null;
    if (legacy) {
      const guest0 = (ev.attendees || []).find((a) => a && !a.organizer && !a.self) || {};
      const bookedAt = parsePh(row['Booked at (PH)']);
      p = {
        rr: '1', rrKey: '', rrName: row.Name || guest0.displayName || '', rrEmail: String(row.Email || guest0.email || '').toLowerCase(),
        rrTz: row['Visitor time zone'] || '', rrStart: start, rrSet: String(Number.isFinite(bookedAt) ? bookedAt : 0),
        rrChanges: '0', rrDay: '', rrHour: '', rrState: '',
      };
      changed = true;
    }

    const guest = (ev.attendees || []).find((a) => a && String(a.email || '').toLowerCase() === p.rrEmail);
    if (guest && guest.responseStatus === 'declined') {
      if (p.rrState !== 'declined') items.push({ eventId: ev.id, patch: { extendedProperties: { private: { ...p, rrState: 'declined' } } }, sheet: { 'Calendar link': ev.htmlLink, Status: 'Declined' } });
      else if (changed) items.push({ eventId: ev.id, patch: { extendedProperties: { private: p } } });
      continue; // no reminders for a declined invite
    }
    if (p.rrState === 'declined') { p.rrState = ''; changed = true; sheet = { 'Calendar link': ev.htmlLink, Status: 'Booked' }; }

    // Moved in Google Calendar (by Jeff, or by a change the sweep hasn't seen): follow the new time.
    if (Date.parse(p.rrStart) !== startMs) {
      moves.push({ email: p.rrEmail, from: p.rrStart, to: start });
      p = { ...p, rrStart: start, rrSet: String(nowMs) };
      changed = true;
      sheet = { 'Calendar link': ev.htmlLink, ...sheetTimes(startMs), Status: 'Rescheduled' };
    }

    // Reminders for the event's current time. The sweep runs every 10 minutes.
    let email = null;
    const ahead = startMs - nowMs;
    const data = { name: p.rrName, email: p.rrEmail, tz: p.rrTz, start, meet: ev.hangoutLink || '', key: p.rrKey };
    if (p.rrHour !== start && ahead <= HOUR_MS && ahead > 10 * MINUTE_MS) {
      email = reminderEmail('hour', data);
      p = { ...p, rrHour: start, rrDay: start };
    } else if (p.rrDay !== start && ahead <= 24 * HOUR_MS && ahead > 2 * HOUR_MS && startMs - (Number(p.rrSet) || 0) >= 24 * HOUR_MS + 5 * MINUTE_MS) {
      // Skipped when the booking (or the last move) was made less than a day ahead, as before.
      email = reminderEmail('day', data);
      p = { ...p, rrDay: start };
    }
    if (email && !p.rrEmail) email = null;
    if (changed || email) items.push({ eventId: ev.id, patch: { extendedProperties: { private: p } }, ...(email ? { email } : {}), ...(sheet ? { sheet } : {}) });
  }

  // Cancelled in Google Calendar: a sheet row still "Booked" or "Rescheduled" whose event is gone.
  // Only when Google's list is complete, so a short or failed read never marks real bookings as cancelled.
  if (complete) {
    for (const row of rows || []) {
      const link = row && row['Calendar link'];
      const t = row ? rowStart(row) : NaN;
      if (!link || !['Booked', 'Rescheduled'].includes(String(row.Status || '').trim())) continue;
      if (!(t > nowMs && t < nowMs + (LIST_DAYS - 1) * 24 * HOUR_MS) || links.has(link)) continue;
      items.push({ sheet: { 'Calendar link': link, Status: 'Cancelled' } });
      moves.push({ email: String(row.Email || '').toLowerCase(), from: iso(t), to: null });
    }
  }
  return { items, moves };
}

// Booking request checks, run inside the n8n workflow before anything touches the calendar.
// The pop-up validates too, but the webhook is public, so these checks are the real gate.
// Copied into n8n by tools/build_n8n.mjs together with slots.js and manage.js (the import lines are dropped there).

const BOOKING_LIMITS = {
  name: 80, email: 254, company: 120, process: 400, summary: 2000, tz: 64,
  perEmailUpcoming: 1,     // one upcoming review per email address
  perDay: 6,               // new bookings accepted in any 24 hours, across everyone
};

// The opening of the calendar invite the visitor receives. Update the link if the site moves to its own domain.
const INVITE_PREP = [
  'Bring one report or check your team keeps redoing. Live example: https://rework-rescue.vercel.app/#samples',
  'No files or prep needed. Please leave out anything confidential.',
  '',
  'Your details',
];

// 20 Nov 2026: each booking gets a private link to change or cancel it (src/booking/manage.js).
const CHANGE_LINE = 'Need a different time? Change or cancel here:';

const clean = (v, max) => String(v ?? '').replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/g, '').replace(/[ \t]+/g, ' ').trim().slice(0, max);
const EMAIL = /^[^\s@<>()[\]\\,;:"]+@[^\s@<>()[\]\\,;:"]+\.[^\s@<>()[\]\\,;:"]{2,}$/;

const fmtHost = (ms) => new Intl.DateTimeFormat('en-US', {
  timeZone: 'Asia/Manila', weekday: 'long', month: 'long', day: 'numeric', hour: 'numeric', minute: '2-digit',
}).format(new Date(ms));

/**
 * @param {object} body     the JSON the pop-up sent
 * @param {number} nowMs
 * @param {{email:string, slot:string, at:number}[]} history  bookings this workflow accepted before
 * @param {object} [rules]
 * @param {string} [key]  the change-link key (from the n8n Crypto node); a fallback key is made if it's missing
 * @returns {{ok:true, booking:object, event:object, notify:object} | {ok:false, status:number, code:string}}
 */
function checkBooking(body, nowMs, history = [], rules = RULES, key = '') {
  const b = body && typeof body === 'object' ? body : {};
  // Honeypot: a hidden field people never fill in. Pretend it worked so bots don't learn anything.
  if (clean(b.website, 200)) return { ok: false, status: 200, code: 'ok' };

  const name = clean(b.name, BOOKING_LIMITS.name + 1);
  const email = clean(b.email, BOOKING_LIMITS.email + 1).toLowerCase();
  const company = clean(b.company, BOOKING_LIMITS.company);
  const process = clean(b.process, BOOKING_LIMITS.process);
  const summary = String(b.summary ?? '').replace(/\r/g, '').trim().slice(0, BOOKING_LIMITS.summary);
  const tz = clean(b.tz, BOOKING_LIMITS.tz);
  const slot = clean(b.slot, 40);

  if (!name || name.length > BOOKING_LIMITS.name) return { ok: false, status: 400, code: 'name' };
  if (!EMAIL.test(email) || email.length > BOOKING_LIMITS.email) return { ok: false, status: 400, code: 'email' };
  if (!isAllowedSlot(slot, nowMs, rules)) return { ok: false, status: 400, code: 'slot' };

  const startMs = Date.parse(slot);
  const endMs = startMs + rules.slotMinutes * 60e3;
  const upcoming = history.filter((h) => h.email === email && Date.parse(h.slot) > nowMs);
  if (upcoming.length >= BOOKING_LIMITS.perEmailUpcoming) return { ok: false, status: 429, code: 'already_booked' };
  if (history.filter((h) => nowMs - h.at < 24 * 3600e3).length >= BOOKING_LIMITS.perDay) return { ok: false, status: 429, code: 'busy' };

  const start = new Date(startMs).toISOString();
  const end = new Date(endMs).toISOString();
  const whenHost = `${fmtHost(startMs)} Philippine time`;
  const changeKey = KEY_RE.test(String(key)) ? String(key) : newKey();
  const footer = '\nBooked through the Rework Rescue website.';
  const resultLine = summary ? `\nFind Your Rework result:\n${summary}` : '';

  // Invite: what the visitor sees. No time zone line; Google Calendar already shows their local time.
  const inviteLines = [
    `Name: ${name}`, `Email: ${email}`, company ? `Company: ${company}` : '',
    process ? `Report or process: ${process}` : '', resultLine, footer,
  ].filter(Boolean);

  // Notification: what Jeff sees. Keeps the visitor's time zone.
  const notifyLines = [
    `Name: ${name}`, `Email: ${email}`, company ? `Company: ${company}` : '',
    process ? `Report or process: ${process}` : '', tz ? `Visitor's time zone: ${tz}` : '',
    resultLine, footer,
  ].filter(Boolean);

  return {
    ok: true,
    booking: { name, email, company, process, summary, tz, start, end, key: changeKey },
    event: {
      summary: EVENT_TITLE,
      description: [...INVITE_PREP.slice(0, 2), `${CHANGE_LINE} ${changeLink(changeKey)}`, ...INVITE_PREP.slice(2), ...inviteLines].join('\n'),
      start: { dateTime: start },
      end: { dateTime: end },
      attendees: [{ email, displayName: name }],
      conferenceData: { createRequest: { requestId: `rr-${startMs}-${Math.random().toString(36).slice(2, 10)}`, conferenceSolutionKey: { type: 'hangoutsMeet' } } },
      reminders: { useDefault: true },
      // Private to Jeff's calendar: the change-link key and what the reminders need. Guests never see these.
      extendedProperties: { private: bookingProps({ key: changeKey, name, email, tz, start, nowMs }) },
    },
    notify: {
      subject: `New review booked: ${name}${company ? ` (${company})` : ''}, ${whenHost}`,
      text: [`New free review booked for ${whenHost}.`, '', ...notifyLines, '', 'The calendar invite with the Meet link has been sent to them.'].join('\n'),
    },
  };
}

/**
 * Clear remembered bookings so an email can book again (Jeff's reset link; doesn't touch the calendar or sheet).
 * `email` is one address (any case), or 'all' to clear the whole list.
 * @returns {{history:object[], removed:number}}
 */
function forgetBooking(history, email) {
  const list = history || [];
  const target = String(email ?? '').trim().toLowerCase();
  if (!target) return { history: list, removed: 0 };
  const kept = target === 'all' ? [] : list.filter((h) => h.email !== target);
  return { history: kept, removed: list.length - kept.length };
}

/**
 * Keep the remembered bookings in step after a change: `to` is the new start (ISO), or null when cancelled.
 * Only the entry for that email and old start changes.
 */
function moveBooking(history, { email, from, to }) {
  const target = String(email ?? '').trim().toLowerCase();
  const fromMs = Date.parse(from);
  const same = (h) => h.email === target && Date.parse(h.slot) === fromMs;
  const list = history || [];
  return to ? list.map((h) => (same(h) ? { ...h, slot: to } : h)) : list.filter((h) => !same(h));
}

/** Bookings worth remembering for the limits: drop entries more than a day old whose slot has passed. */
function pruneHistory(history, nowMs) {
  return (history || []).filter((h) => Date.parse(h.slot) > nowMs || nowMs - h.at < 24 * 3600e3);
}

// Google Sheet log: one row per booking. Create a sheet whose first row has exactly these headers.
const SHEET_COLUMNS = [
  'Booked at (PH)', 'Review time (PH)', 'Review time (UTC)', 'Name', 'Email', 'Company',
  'Report or process', 'Visitor time zone', 'Find Your Rework result', 'Meet link', 'Calendar link', 'Status',
];

const fmtSheet = (ms) => new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Asia/Manila', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false,
}).format(new Date(ms)).replace(',', '');

/** The sheet row for a booking that went through. Status starts as "Booked" for Jeff to update by hand. */
function sheetRow(booking, { meet = '', eventLink = '', nowMs = Date.now() } = {}) {
  // A leading = + - @ would make Sheets treat a visitor's text as a formula; prefix those with an apostrophe.
  const safe = (v) => { const s = String(v ?? ''); return /^[=+\-@]/.test(s) ? `'${s}` : s; };
  const values = [
    fmtSheet(nowMs), fmtSheet(Date.parse(booking.start)), booking.start, booking.name, booking.email, booking.company,
    booking.process, booking.tz, booking.summary, meet, eventLink, 'Booked',
  ];
  return Object.fromEntries(SHEET_COLUMNS.map((c, i) => [c, i < 3 ? values[i] : safe(values[i])]));
}

// ---------------------------------------------------------------- Reminder emails to the visitor
// Sent by the workflow 1 day and 1 hour before the review, in the visitor's own time zone.
const SITE_EXAMPLES = 'https://rework-rescue.vercel.app/#samples';

function visitorTime(ms, tz) {
  const opts = { weekday: 'long', month: 'long', day: 'numeric', hour: 'numeric', minute: '2-digit', timeZoneName: 'short' };
  try { return new Intl.DateTimeFormat('en-US', { ...opts, timeZone: tz || 'Asia/Manila' }).format(new Date(ms)); }
  catch { return new Intl.DateTimeFormat('en-US', { ...opts, timeZone: 'Asia/Manila' }).format(new Date(ms)); }
}

/**
 * The reminder emails, in the visitor's own time zone. kind: 'day' (1 day before) or 'hour' (1 hour before).
 * When the booking is sent by src/booking/manage.js (sweepReminders), which decides when each one is due.
 * key: the change-link key; without one (bookings made before 20 Nov) the email says to reply instead.
 */
function reminderEmail(kind, { name = '', email = '', tz = '', start, meet = '', key = '' }) {
  const startMs = Date.parse(start);
  const when = visitorTime(startMs, tz);
  const first = String(name || '').split(' ')[0] || 'there';
  const join = meet ? `Join with Google Meet: ${meet}` : 'The Google Meet link is in your calendar invite.';
  const sign = ['Jeff Herson Vida', 'Rework Rescue · Less rework. More real work.'];
  const link = KEY_RE.test(String(key)) ? changeLink(key) : '';
  if (kind === 'day') {
    return {
      to: email,
      subject: 'Reminder: your free review is tomorrow',
      text: [
        `Hi ${first},`, '',
        'A quick reminder of your free 30-minute review with me tomorrow:', when, join, '',
        `Before the call, have one report, check or workflow in mind that your team keeps redoing, like the examples on my site: ${SITE_EXAMPLES}`,
        'No preparation or files needed, and please leave out anything confidential.', '',
        link ? `${CHANGE_LINE} ${link}` : 'Need to change the time? Just reply to this email.', '', ...sign,
      ].join('\n'),
    };
  }
  return {
    to: email,
    subject: 'Starting in an hour: your free review',
    text: [
      `Hi ${first},`, '', `Your free review starts in an hour: ${when}.`, join, '',
      link ? `Can't make it? Change or cancel here: ${link}` : "Can't make it? Just reply to this email.", '',
      'See you soon,', ...sign,
    ].join('\n'),
  };
}

// ---- workflow step
const store = $getWorkflowStaticData('global');
store.bookings = pruneHistory(store.bookings, Date.now());
return [{ json: checkBooking($input.first().json.body, Date.now(), store.bookings, RULES, $input.first().json.changeKey) }];

// Kept for the limits in check.js (one upcoming review per email, daily cap). Only email, time and when it was booked.
const b = $('Check the request').first().json.booking;
const store = $getWorkflowStaticData('global');
store.bookings = (store.bookings || []).concat({ email: b.email, slot: b.start, at: Date.now() });
return [{ json: { start: b.start, meet: $input.first().json.hangoutLink || '' } }];

// Booking slot rules: the ONE place that decides which times can be booked.
//
// Used in two places:
//  - the n8n workflow (copied into its Code nodes by tools/build_n8n.mjs), which checks Google Calendar
//    and returns only the free slots, and re-checks a slot before booking it;
//  - the booking pop-up (src/ui/booking.js), only as a fallback while n8n isn't connected.
//
// Change the hours here, run `node tools/build_n8n.mjs`, and re-import n8n/rework-review-booking.json.
// Keep this file free of imports and browser/Node-only APIs: it must run inside an n8n Code node.

const RULES = {
  hostOffsetHours: 8,          // Philippine time, UTC+8, no daylight saving
  days: [1, 2, 3, 4, 5],       // days a window STARTS on (0 = Sunday): Monday to Friday
  start: '08:00',              // first start time, Philippine time
  end: '02:00',                // window ends at this time; earlier than start means the next day (Fri 8:00 am to Sat 2:00 am)
  slotMinutes: 30,             // meeting length, and the step between start times
  minNoticeHours: 12,          // no bookings sooner than this
  daysAhead: 28,               // how far ahead people can book
};

const MIN = 60e3;

function toMinutes(hhmm) {
  const [h, m] = hhmm.split(':').map(Number);
  return h * 60 + m;
}

/** Every bookable start time (ms since epoch, UTC) from now, before checking the calendar. */
function candidateSlots(nowMs, rules = RULES) {
  const off = rules.hostOffsetHours * 60 * MIN;
  const startMin = toMinutes(rules.start);
  let endMin = toMinutes(rules.end);
  if (endMin <= startMin) endMin += 24 * 60;
  const earliest = nowMs + rules.minNoticeHours * 60 * MIN;
  const latest = nowMs + rules.daysAhead * 24 * 60 * MIN;

  // Host-local midnight of "today", as a UTC timestamp. Start one day back so a window that began
  // yesterday evening and runs past midnight is still included.
  const hostNow = new Date(nowMs + off);
  const todayMidnight = Date.UTC(hostNow.getUTCFullYear(), hostNow.getUTCMonth(), hostNow.getUTCDate()) - off;

  const out = [];
  for (let i = -1; i <= rules.daysAhead + 1; i++) {
    const dayStart = todayMidnight + i * 24 * 60 * MIN;
    const weekday = new Date(dayStart + off).getUTCDay();
    if (!rules.days.includes(weekday)) continue;
    for (let m = startMin; m + rules.slotMinutes <= endMin; m += rules.slotMinutes) {
      const t = dayStart + m * MIN;
      if (t >= earliest && t <= latest) out.push(t);
    }
  }
  return out;
}

/** Free start times: candidates that don't overlap any busy period ({start, end} ISO strings). */
function freeSlots(nowMs, busy = [], rules = RULES) {
  const periods = busy
    .map((b) => [Date.parse(b.start), Date.parse(b.end)])
    .filter(([s, e]) => Number.isFinite(s) && Number.isFinite(e));
  const len = rules.slotMinutes * MIN;
  return candidateSlots(nowMs, rules).filter((t) => !periods.some(([s, e]) => t < e && t + len > s));
}

/** True if this exact start time (ISO string) is one the rules allow. Does not check the calendar. */
function isAllowedSlot(iso, nowMs, rules = RULES) {
  const t = Date.parse(iso);
  if (!Number.isFinite(t)) return false;
  return candidateSlots(nowMs, rules).includes(t);
}

// Change or cancel a booking, and the reminder sweep. Run inside the n8n booking workflow (tools/build_n8n.mjs
// copies this file in with slots.js and check.js; import lines are dropped there). 20 Nov 2026, Jeff: automated.
//
// How it fits together
//  - Every booking's Google Calendar event carries private details (extendedProperties.private, visible only on
//    Jeff's calendar): a random key, the visitor's name, email and time zone, the start the workflow knows about,
//    how many times it was changed, and which reminders went out.
//  - The invite and reminders link to https://rework-rescue.vercel.app/#booking=KEY. The pop-up sends that key to
//    the rr-manage webhook to look the booking up, move it (same event, same Meet link) or cancel it.
//  - Every 10 minutes the workflow reads the calendar and the bookings sheet (sweepReminders): it sends reminders
//    that are due for the event's CURRENT time, notices when Jeff moved or cancelled a review in Google Calendar,
//    or the visitor declined the invite, and keeps the sheet in step.
//
// Keep this file free of browser/Node-only APIs: it must run inside an n8n Code node.

const CHANGE_RULES = {
  maxChanges: 2,            // a visitor can move one booking twice; after that, "reply to the invite"
  // New times follow the normal booking rules in slots.js (12 hours' notice, up to 28 days ahead).
  // Moving or cancelling is possible until the review starts.
};
const SITE_URL = 'https://rework-rescue.vercel.app/';
const EVENT_TITLE = 'Free review with Jeff (Rework Rescue)';
const KEY_RE = /^[A-Za-z0-9]{24,64}$/;
const LIST_DAYS = 60; // how far ahead the sweep reads the calendar (bookings go 28 days ahead)

const HOUR_MS = 3600e3;
const MINUTE_MS = 60e3;

/** The visitor's private link. A #fragment, so the key never reaches a server log or another site. */
const changeLink = (key) => `${SITE_URL}#booking=${key}`;

/** Fallback key if the n8n Crypto node didn't supply one (it normally does). */
function newKey(rand = Math.random) {
  const abc = 'abcdefghijklmnopqrstuvwxyz0123456789';
  let k = '';
  for (let i = 0; i < 32; i++) k += abc[Math.floor(rand() * abc.length) % abc.length];
  return k;
}

/** What a new booking keeps on its calendar event. Google needs every value as a string. */
function bookingProps({ key, name, email, tz, start, nowMs }) {
  return {
    rr: '1', rrKey: key, rrName: name, rrEmail: email, rrTz: tz || '', rrStart: new Date(Date.parse(start)).toISOString(),
    rrSet: String(nowMs), rrChanges: '0', rrDay: '', rrHour: '', rrState: '',
  };
}

const iso = (ms) => new Date(ms).toISOString();
const props = (ev) => ({ ...((ev && ev.extendedProperties && ev.extendedProperties.private) || {}) });
const sheetTimes = (ms) => ({ 'Review time (PH)': fmtSheet(ms), 'Review time (UTC)': iso(ms) });
const host = (ms) => `${fmtHost(ms)} Philippine time`;

// ---------------------------------------------------------------- rr-manage webhook

/**
 * First check of a change request, before Google is asked anything.
 * body: { key, action: 'look' | 'move' | 'cancel', slot? (ISO, for move) }
 */
function checkChange(body, nowMs, rules = RULES) {
  const b = body && typeof body === 'object' ? body : {};
  const key = String(b.key ?? '').trim();
  const action = String(b.action ?? '');
  if (!KEY_RE.test(key)) return { ok: false, status: 404, code: 'not_found' };
  if (!['look', 'move', 'cancel'].includes(action)) return { ok: false, status: 400, code: 'action' };
  if (action !== 'move') return { ok: true, key, action };
  const slot = String(b.slot ?? '').slice(0, 40);
  if (!isAllowedSlot(slot, nowMs, rules)) return { ok: false, status: 400, code: 'slot' };
  const startMs = Date.parse(slot);
  return { ok: true, key, action, start: iso(startMs), end: iso(startMs + rules.slotMinutes * MINUTE_MS) };
}

/**
 * Decide what to do, given the request (checkChange) and Google's answer to
 * events?privateExtendedProperty=rrKey=KEY. Returns what to answer, and for move/cancel what to change.
 */
function decideChange(req, list, nowMs, rules = CHANGE_RULES) {
  const no = (status, code) => ({ ok: false, status, code, respond: { ok: false, error: code } });
  const items = (list && Array.isArray(list.items)) ? list.items : [];
  const ev = items.find((e) => e && e.status !== 'cancelled' && props(e).rrKey === req.key && e.start && e.start.dateTime);
  if (!ev) return no(404, 'not_found');
  const p = props(ev);
  const startMs = Date.parse(ev.start.dateTime);
  const endMs = Date.parse((ev.end && ev.end.dateTime) || '') || startMs + 30 * MINUTE_MS;
  if (!(startMs > nowMs)) return no(410, 'started');
  const changes = Number(p.rrChanges) || 0;
  const left = Math.max(0, rules.maxChanges - changes);
  const name = p.rrName || '';
  const first = name.split(' ')[0] || '';
  const base = { eventId: ev.id, link: ev.htmlLink || '', email: p.rrEmail || '', from: iso(startMs) };

  if (req.action === 'look') {
    return { ok: true, status: 200, action: 'look', respond: { ok: true, start: iso(startMs), end: iso(endMs), name: first, changesLeft: left } };
  }

  const who = [`Name: ${name}`, `Email: ${p.rrEmail || ''}`, p.rrTz ? `Visitor's time zone: ${p.rrTz}` : ''].filter(Boolean);

  if (req.action === 'move') {
    if (left <= 0) return no(409, 'no_changes_left');
    const toMs = Date.parse(req.start);
    if (toMs === startMs) return no(400, 'same_time');
    return {
      ok: true, status: 200, action: 'move', ...base, to: iso(toMs),
      patch: {
        start: { dateTime: req.start }, end: { dateTime: req.end },
        extendedProperties: { private: { ...p, rrStart: iso(toMs), rrSet: String(nowMs), rrChanges: String(changes + 1), rrDay: '', rrHour: '', rrState: '' } },
      },
      sheet: { 'Calendar link': ev.htmlLink || '', ...sheetTimes(toMs), Status: 'Rescheduled' },
      notify: {
        subject: `Review moved: ${name}, now ${host(toMs)}`,
        text: [`${name} moved their free review using the change link.`, '', `From: ${host(startMs)}`, `To:   ${host(toMs)}`, '',
          ...who, '', 'The calendar event and their invite are updated. The Meet link stays the same.',
          `Changes used: ${changes + 1} of ${rules.maxChanges}.`].join('\n'),
      },
      respond: { ok: true, action: 'move', start: iso(toMs), end: req.end, changesLeft: left - 1 },
    };
  }

  // cancel
  return {
    ok: true, status: 200, action: 'cancel', ...base, to: null,
    sheet: { 'Calendar link': ev.htmlLink || '', Status: 'Cancelled' },
    notify: {
      subject: `Review cancelled: ${name}, ${host(startMs)}`,
      text: [`${name} cancelled their free review using the change link.`, '', `Was: ${host(startMs)}`, '', ...who, '',
        'The calendar event is cancelled and Google has told them. Their email can book again.'].join('\n'),
    },
    respond: { ok: true, action: 'cancel' },
  };
}

// ---------------------------------------------------------------- 10-minute sweep: reminders and keeping in step

/** "2026-11-24 09:00" (or with seconds) in Philippine time, as the sheet shows it. */
function parsePh(v) {
  const m = String(v ?? '').match(/(\d{4})-(\d{2})-(\d{2})[ T,]+(\d{1,2}):(\d{2})/);
  if (!m) return NaN;
  return Date.UTC(+m[1], +m[2] - 1, +m[3], +m[4] - 8, +m[5]);
}
function rowStart(row) {
  const utc = String(row['Review time (UTC)'] ?? '');
  if (/Z$|[+-]\d\d:\d\d$/.test(utc) && Number.isFinite(Date.parse(utc))) return Date.parse(utc);
  return parsePh(row['Review time (PH)']);
}

/**
 * @param {object} list   Google events.list for now .. now + LIST_DAYS (singleEvents), ALL events on the calendar
 * @param {object[]} rows the bookings sheet rows (header names as keys)
 * @param {number} nowMs
 * @returns {{items: object[], moves: {email, from, to}[]}}
 *   items: one per thing to do, with any of
 *     eventId + patch  (update the event's private details; done BEFORE the email so a reminder is never sent twice)
 *     email            ({to, subject, text})
 *     sheet            (row update, matched on 'Calendar link')
 *   moves: for the remembered bookings (to = null: cancelled)
 */
function sweepReminders(list, rows, nowMs) {
  if (!list || !Array.isArray(list.items)) throw new Error('Google Calendar list missing: ' + JSON.stringify(list).slice(0, 300));
  const complete = !list.nextPageToken;
  const events = list.items.filter((e) => e && e.status !== 'cancelled');
  const links = new Set(events.map((e) => e.htmlLink).filter(Boolean));
  const rowByLink = new Map((rows || []).filter((r) => r && r['Calendar link']).map((r) => [r['Calendar link'], r]));
  const items = [];
  const moves = [];

  for (const ev of events) {
    let p = props(ev);
    const row = rowByLink.get(ev.htmlLink);
    const tagged = p.rr === '1';
    // Bookings made before 20 Nov have no private details: adopt them from their sheet row (no change link).
    const legacy = !tagged && ev.summary === EVENT_TITLE && !!row;
    if (!tagged && !legacy) continue;
    if (!ev.start || !ev.start.dateTime) continue;
    const startMs = Date.parse(ev.start.dateTime);
    if (!(startMs > nowMs)) continue;
    const start = iso(startMs);
    let changed = false;
    let sheet = null;
    if (legacy) {
      const guest0 = (ev.attendees || []).find((a) => a && !a.organizer && !a.self) || {};
      const bookedAt = parsePh(row['Booked at (PH)']);
      p = {
        rr: '1', rrKey: '', rrName: row.Name || guest0.displayName || '', rrEmail: String(row.Email || guest0.email || '').toLowerCase(),
        rrTz: row['Visitor time zone'] || '', rrStart: start, rrSet: String(Number.isFinite(bookedAt) ? bookedAt : 0),
        rrChanges: '0', rrDay: '', rrHour: '', rrState: '',
      };
      changed = true;
    }

    const guest = (ev.attendees || []).find((a) => a && String(a.email || '').toLowerCase() === p.rrEmail);
    if (guest && guest.responseStatus === 'declined') {
      if (p.rrState !== 'declined') items.push({ eventId: ev.id, patch: { extendedProperties: { private: { ...p, rrState: 'declined' } } }, sheet: { 'Calendar link': ev.htmlLink, Status: 'Declined' } });
      else if (changed) items.push({ eventId: ev.id, patch: { extendedProperties: { private: p } } });
      continue; // no reminders for a declined invite
    }
    if (p.rrState === 'declined') { p.rrState = ''; changed = true; sheet = { 'Calendar link': ev.htmlLink, Status: 'Booked' }; }

    // Moved in Google Calendar (by Jeff, or by a change the sweep hasn't seen): follow the new time.
    if (Date.parse(p.rrStart) !== startMs) {
      moves.push({ email: p.rrEmail, from: p.rrStart, to: start });
      p = { ...p, rrStart: start, rrSet: String(nowMs) };
      changed = true;
      sheet = { 'Calendar link': ev.htmlLink, ...sheetTimes(startMs), Status: 'Rescheduled' };
    }

    // Reminders for the event's current time. The sweep runs every 10 minutes.
    let email = null;
    const ahead = startMs - nowMs;
    const data = { name: p.rrName, email: p.rrEmail, tz: p.rrTz, start, meet: ev.hangoutLink || '', key: p.rrKey };
    if (p.rrHour !== start && ahead <= HOUR_MS && ahead > 10 * MINUTE_MS) {
      email = reminderEmail('hour', data);
      p = { ...p, rrHour: start, rrDay: start };
    } else if (p.rrDay !== start && ahead <= 24 * HOUR_MS && ahead > 2 * HOUR_MS && startMs - (Number(p.rrSet) || 0) >= 24 * HOUR_MS + 5 * MINUTE_MS) {
      // Skipped when the booking (or the last move) was made less than a day ahead, as before.
      email = reminderEmail('day', data);
      p = { ...p, rrDay: start };
    }
    if (email && !p.rrEmail) email = null;
    if (changed || email) items.push({ eventId: ev.id, patch: { extendedProperties: { private: p } }, ...(email ? { email } : {}), ...(sheet ? { sheet } : {}) });
  }

  // Cancelled in Google Calendar: a sheet row still "Booked" or "Rescheduled" whose event is gone.
  // Only when Google's list is complete, so a short or failed read never marks real bookings as cancelled.
  if (complete) {
    for (const row of rows || []) {
      const link = row && row['Calendar link'];
      const t = row ? rowStart(row) : NaN;
      if (!link || !['Booked', 'Rescheduled'].includes(String(row.Status || '').trim())) continue;
      if (!(t > nowMs && t < nowMs + (LIST_DAYS - 1) * 24 * HOUR_MS) || links.has(link)) continue;
      items.push({ sheet: { 'Calendar link': link, Status: 'Cancelled' } });
      moves.push({ email: String(row.Email || '').toLowerCase(), from: iso(t), to: null });
    }
  }
  return { items, moves };
}

// Booking request checks, run inside the n8n workflow before anything touches the calendar.
// The pop-up validates too, but the webhook is public, so these checks are the real gate.
// Copied into n8n by tools/build_n8n.mjs together with slots.js and manage.js (the import lines are dropped there).

const BOOKING_LIMITS = {
  name: 80, email: 254, company: 120, process: 400, summary: 2000, tz: 64,
  perEmailUpcoming: 1,     // one upcoming review per email address
  perDay: 6,               // new bookings accepted in any 24 hours, across everyone
};

// The opening of the calendar invite the visitor receives. Update the link if the site moves to its own domain.
const INVITE_PREP = [
  'Bring one report or check your team keeps redoing. Live example: https://rework-rescue.vercel.app/#samples',
  'No files or prep needed. Please leave out anything confidential.',
  '',
  'Your details',
];

// 20 Nov 2026: each booking gets a private link to change or cancel it (src/booking/manage.js).
const CHANGE_LINE = 'Need a different time? Change or cancel here:';

const clean = (v, max) => String(v ?? '').replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/g, '').replace(/[ \t]+/g, ' ').trim().slice(0, max);
const EMAIL = /^[^\s@<>()[\]\\,;:"]+@[^\s@<>()[\]\\,;:"]+\.[^\s@<>()[\]\\,;:"]{2,}$/;

const fmtHost = (ms) => new Intl.DateTimeFormat('en-US', {
  timeZone: 'Asia/Manila', weekday: 'long', month: 'long', day: 'numeric', hour: 'numeric', minute: '2-digit',
}).format(new Date(ms));

/**
 * @param {object} body     the JSON the pop-up sent
 * @param {number} nowMs
 * @param {{email:string, slot:string, at:number}[]} history  bookings this workflow accepted before
 * @param {object} [rules]
 * @param {string} [key]  the change-link key (from the n8n Crypto node); a fallback key is made if it's missing
 * @returns {{ok:true, booking:object, event:object, notify:object} | {ok:false, status:number, code:string}}
 */
function checkBooking(body, nowMs, history = [], rules = RULES, key = '') {
  const b = body && typeof body === 'object' ? body : {};
  // Honeypot: a hidden field people never fill in. Pretend it worked so bots don't learn anything.
  if (clean(b.website, 200)) return { ok: false, status: 200, code: 'ok' };

  const name = clean(b.name, BOOKING_LIMITS.name + 1);
  const email = clean(b.email, BOOKING_LIMITS.email + 1).toLowerCase();
  const company = clean(b.company, BOOKING_LIMITS.company);
  const process = clean(b.process, BOOKING_LIMITS.process);
  const summary = String(b.summary ?? '').replace(/\r/g, '').trim().slice(0, BOOKING_LIMITS.summary);
  const tz = clean(b.tz, BOOKING_LIMITS.tz);
  const slot = clean(b.slot, 40);

  if (!name || name.length > BOOKING_LIMITS.name) return { ok: false, status: 400, code: 'name' };
  if (!EMAIL.test(email) || email.length > BOOKING_LIMITS.email) return { ok: false, status: 400, code: 'email' };
  if (!isAllowedSlot(slot, nowMs, rules)) return { ok: false, status: 400, code: 'slot' };

  const startMs = Date.parse(slot);
  const endMs = startMs + rules.slotMinutes * 60e3;
  const upcoming = history.filter((h) => h.email === email && Date.parse(h.slot) > nowMs);
  if (upcoming.length >= BOOKING_LIMITS.perEmailUpcoming) return { ok: false, status: 429, code: 'already_booked' };
  if (history.filter((h) => nowMs - h.at < 24 * 3600e3).length >= BOOKING_LIMITS.perDay) return { ok: false, status: 429, code: 'busy' };

  const start = new Date(startMs).toISOString();
  const end = new Date(endMs).toISOString();
  const whenHost = `${fmtHost(startMs)} Philippine time`;
  const changeKey = KEY_RE.test(String(key)) ? String(key) : newKey();
  const footer = '\nBooked through the Rework Rescue website.';
  const resultLine = summary ? `\nFind Your Rework result:\n${summary}` : '';

  // Invite: what the visitor sees. No time zone line; Google Calendar already shows their local time.
  const inviteLines = [
    `Name: ${name}`, `Email: ${email}`, company ? `Company: ${company}` : '',
    process ? `Report or process: ${process}` : '', resultLine, footer,
  ].filter(Boolean);

  // Notification: what Jeff sees. Keeps the visitor's time zone.
  const notifyLines = [
    `Name: ${name}`, `Email: ${email}`, company ? `Company: ${company}` : '',
    process ? `Report or process: ${process}` : '', tz ? `Visitor's time zone: ${tz}` : '',
    resultLine, footer,
  ].filter(Boolean);

  return {
    ok: true,
    booking: { name, email, company, process, summary, tz, start, end, key: changeKey },
    event: {
      summary: EVENT_TITLE,
      description: [...INVITE_PREP.slice(0, 2), `${CHANGE_LINE} ${changeLink(changeKey)}`, ...INVITE_PREP.slice(2), ...inviteLines].join('\n'),
      start: { dateTime: start },
      end: { dateTime: end },
      attendees: [{ email, displayName: name }],
      conferenceData: { createRequest: { requestId: `rr-${startMs}-${Math.random().toString(36).slice(2, 10)}`, conferenceSolutionKey: { type: 'hangoutsMeet' } } },
      reminders: { useDefault: true },
      // Private to Jeff's calendar: the change-link key and what the reminders need. Guests never see these.
      extendedProperties: { private: bookingProps({ key: changeKey, name, email, tz, start, nowMs }) },
    },
    notify: {
      subject: `New review booked: ${name}${company ? ` (${company})` : ''}, ${whenHost}`,
      text: [`New free review booked for ${whenHost}.`, '', ...notifyLines, '', 'The calendar invite with the Meet link has been sent to them.'].join('\n'),
    },
  };
}

/**
 * Clear remembered bookings so an email can book again (Jeff's reset link; doesn't touch the calendar or sheet).
 * `email` is one address (any case), or 'all' to clear the whole list.
 * @returns {{history:object[], removed:number}}
 */
function forgetBooking(history, email) {
  const list = history || [];
  const target = String(email ?? '').trim().toLowerCase();
  if (!target) return { history: list, removed: 0 };
  const kept = target === 'all' ? [] : list.filter((h) => h.email !== target);
  return { history: kept, removed: list.length - kept.length };
}

/**
 * Keep the remembered bookings in step after a change: `to` is the new start (ISO), or null when cancelled.
 * Only the entry for that email and old start changes.
 */
function moveBooking(history, { email, from, to }) {
  const target = String(email ?? '').trim().toLowerCase();
  const fromMs = Date.parse(from);
  const same = (h) => h.email === target && Date.parse(h.slot) === fromMs;
  const list = history || [];
  return to ? list.map((h) => (same(h) ? { ...h, slot: to } : h)) : list.filter((h) => !same(h));
}

/** Bookings worth remembering for the limits: drop entries more than a day old whose slot has passed. */
function pruneHistory(history, nowMs) {
  return (history || []).filter((h) => Date.parse(h.slot) > nowMs || nowMs - h.at < 24 * 3600e3);
}

// Google Sheet log: one row per booking. Create a sheet whose first row has exactly these headers.
const SHEET_COLUMNS = [
  'Booked at (PH)', 'Review time (PH)', 'Review time (UTC)', 'Name', 'Email', 'Company',
  'Report or process', 'Visitor time zone', 'Find Your Rework result', 'Meet link', 'Calendar link', 'Status',
];

const fmtSheet = (ms) => new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Asia/Manila', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false,
}).format(new Date(ms)).replace(',', '');

/** The sheet row for a booking that went through. Status starts as "Booked" for Jeff to update by hand. */
function sheetRow(booking, { meet = '', eventLink = '', nowMs = Date.now() } = {}) {
  // A leading = + - @ would make Sheets treat a visitor's text as a formula; prefix those with an apostrophe.
  const safe = (v) => { const s = String(v ?? ''); return /^[=+\-@]/.test(s) ? `'${s}` : s; };
  const values = [
    fmtSheet(nowMs), fmtSheet(Date.parse(booking.start)), booking.start, booking.name, booking.email, booking.company,
    booking.process, booking.tz, booking.summary, meet, eventLink, 'Booked',
  ];
  return Object.fromEntries(SHEET_COLUMNS.map((c, i) => [c, i < 3 ? values[i] : safe(values[i])]));
}

// ---------------------------------------------------------------- Reminder emails to the visitor
// Sent by the workflow 1 day and 1 hour before the review, in the visitor's own time zone.
const SITE_EXAMPLES = 'https://rework-rescue.vercel.app/#samples';

function visitorTime(ms, tz) {
  const opts = { weekday: 'long', month: 'long', day: 'numeric', hour: 'numeric', minute: '2-digit', timeZoneName: 'short' };
  try { return new Intl.DateTimeFormat('en-US', { ...opts, timeZone: tz || 'Asia/Manila' }).format(new Date(ms)); }
  catch { return new Intl.DateTimeFormat('en-US', { ...opts, timeZone: 'Asia/Manila' }).format(new Date(ms)); }
}

/**
 * The reminder emails, in the visitor's own time zone. kind: 'day' (1 day before) or 'hour' (1 hour before).
 * When the booking is sent by src/booking/manage.js (sweepReminders), which decides when each one is due.
 * key: the change-link key; without one (bookings made before 20 Nov) the email says to reply instead.
 */
function reminderEmail(kind, { name = '', email = '', tz = '', start, meet = '', key = '' }) {
  const startMs = Date.parse(start);
  const when = visitorTime(startMs, tz);
  const first = String(name || '').split(' ')[0] || 'there';
  const join = meet ? `Join with Google Meet: ${meet}` : 'The Google Meet link is in your calendar invite.';
  const sign = ['Jeff Herson Vida', 'Rework Rescue · Less rework. More real work.'];
  const link = KEY_RE.test(String(key)) ? changeLink(key) : '';
  if (kind === 'day') {
    return {
      to: email,
      subject: 'Reminder: your free review is tomorrow',
      text: [
        `Hi ${first},`, '',
        'A quick reminder of your free 30-minute review with me tomorrow:', when, join, '',
        `Before the call, have one report, check or workflow in mind that your team keeps redoing, like the examples on my site: ${SITE_EXAMPLES}`,
        'No preparation or files needed, and please leave out anything confidential.', '',
        link ? `${CHANGE_LINE} ${link}` : 'Need to change the time? Just reply to this email.', '', ...sign,
      ].join('\n'),
    };
  }
  return {
    to: email,
    subject: 'Starting in an hour: your free review',
    text: [
      `Hi ${first},`, '', `Your free review starts in an hour: ${when}.`, join, '',
      link ? `Can't make it? Change or cancel here: ${link}` : "Can't make it? Just reply to this email.", '',
      'See you soon,', ...sign,
    ].join('\n'),
  };
}

// ---- workflow step: one row for the bookings log (headers in SHEET_COLUMNS)
const b = $('Check the request').first().json.booking;
const ev = $('Google: create event + invite').first().json;
return [{ json: sheetRow(b, { meet: ev.hangoutLink || '', eventLink: ev.htmlLink || '' }) }];

// Booking slot rules: the ONE place that decides which times can be booked.
//
// Used in two places:
//  - the n8n workflow (copied into its Code nodes by tools/build_n8n.mjs), which checks Google Calendar
//    and returns only the free slots, and re-checks a slot before booking it;
//  - the booking pop-up (src/ui/booking.js), only as a fallback while n8n isn't connected.
//
// Change the hours here, run `node tools/build_n8n.mjs`, and re-import n8n/rework-review-booking.json.
// Keep this file free of imports and browser/Node-only APIs: it must run inside an n8n Code node.

const RULES = {
  hostOffsetHours: 8,          // Philippine time, UTC+8, no daylight saving
  days: [1, 2, 3, 4, 5],       // days a window STARTS on (0 = Sunday): Monday to Friday
  start: '08:00',              // first start time, Philippine time
  end: '02:00',                // window ends at this time; earlier than start means the next day (Fri 8:00 am to Sat 2:00 am)
  slotMinutes: 30,             // meeting length, and the step between start times
  minNoticeHours: 12,          // no bookings sooner than this
  daysAhead: 28,               // how far ahead people can book
};

const MIN = 60e3;

function toMinutes(hhmm) {
  const [h, m] = hhmm.split(':').map(Number);
  return h * 60 + m;
}

/** Every bookable start time (ms since epoch, UTC) from now, before checking the calendar. */
function candidateSlots(nowMs, rules = RULES) {
  const off = rules.hostOffsetHours * 60 * MIN;
  const startMin = toMinutes(rules.start);
  let endMin = toMinutes(rules.end);
  if (endMin <= startMin) endMin += 24 * 60;
  const earliest = nowMs + rules.minNoticeHours * 60 * MIN;
  const latest = nowMs + rules.daysAhead * 24 * 60 * MIN;

  // Host-local midnight of "today", as a UTC timestamp. Start one day back so a window that began
  // yesterday evening and runs past midnight is still included.
  const hostNow = new Date(nowMs + off);
  const todayMidnight = Date.UTC(hostNow.getUTCFullYear(), hostNow.getUTCMonth(), hostNow.getUTCDate()) - off;

  const out = [];
  for (let i = -1; i <= rules.daysAhead + 1; i++) {
    const dayStart = todayMidnight + i * 24 * 60 * MIN;
    const weekday = new Date(dayStart + off).getUTCDay();
    if (!rules.days.includes(weekday)) continue;
    for (let m = startMin; m + rules.slotMinutes <= endMin; m += rules.slotMinutes) {
      const t = dayStart + m * MIN;
      if (t >= earliest && t <= latest) out.push(t);
    }
  }
  return out;
}

/** Free start times: candidates that don't overlap any busy period ({start, end} ISO strings). */
function freeSlots(nowMs, busy = [], rules = RULES) {
  const periods = busy
    .map((b) => [Date.parse(b.start), Date.parse(b.end)])
    .filter(([s, e]) => Number.isFinite(s) && Number.isFinite(e));
  const len = rules.slotMinutes * MIN;
  return candidateSlots(nowMs, rules).filter((t) => !periods.some(([s, e]) => t < e && t + len > s));
}

/** True if this exact start time (ISO string) is one the rules allow. Does not check the calendar. */
function isAllowedSlot(iso, nowMs, rules = RULES) {
  const t = Date.parse(iso);
  if (!Number.isFinite(t)) return false;
  return candidateSlots(nowMs, rules).includes(t);
}

// Change or cancel a booking, and the reminder sweep. Run inside the n8n booking workflow (tools/build_n8n.mjs
// copies this file in with slots.js and check.js; import lines are dropped there). 20 Nov 2026, Jeff: automated.
//
// How it fits together
//  - Every booking's Google Calendar event carries private details (extendedProperties.private, visible only on
//    Jeff's calendar): a random key, the visitor's name, email and time zone, the start the workflow knows about,
//    how many times it was changed, and which reminders went out.
//  - The invite and reminders link to https://rework-rescue.vercel.app/#booking=KEY. The pop-up sends that key to
//    the rr-manage webhook to look the booking up, move it (same event, same Meet link) or cancel it.
//  - Every 10 minutes the workflow reads the calendar and the bookings sheet (sweepReminders): it sends reminders
//    that are due for the event's CURRENT time, notices when Jeff moved or cancelled a review in Google Calendar,
//    or the visitor declined the invite, and keeps the sheet in step.
//
// Keep this file free of browser/Node-only APIs: it must run inside an n8n Code node.

const CHANGE_RULES = {
  maxChanges: 2,            // a visitor can move one booking twice; after that, "reply to the invite"
  // New times follow the normal booking rules in slots.js (12 hours' notice, up to 28 days ahead).
  // Moving or cancelling is possible until the review starts.
};
const SITE_URL = 'https://rework-rescue.vercel.app/';
const EVENT_TITLE = 'Free review with Jeff (Rework Rescue)';
const KEY_RE = /^[A-Za-z0-9]{24,64}$/;
const LIST_DAYS = 60; // how far ahead the sweep reads the calendar (bookings go 28 days ahead)

const HOUR_MS = 3600e3;
const MINUTE_MS = 60e3;

/** The visitor's private link. A #fragment, so the key never reaches a server log or another site. */
const changeLink = (key) => `${SITE_URL}#booking=${key}`;

/** Fallback key if the n8n Crypto node didn't supply one (it normally does). */
function newKey(rand = Math.random) {
  const abc = 'abcdefghijklmnopqrstuvwxyz0123456789';
  let k = '';
  for (let i = 0; i < 32; i++) k += abc[Math.floor(rand() * abc.length) % abc.length];
  return k;
}

/** What a new booking keeps on its calendar event. Google needs every value as a string. */
function bookingProps({ key, name, email, tz, start, nowMs }) {
  return {
    rr: '1', rrKey: key, rrName: name, rrEmail: email, rrTz: tz || '', rrStart: new Date(Date.parse(start)).toISOString(),
    rrSet: String(nowMs), rrChanges: '0', rrDay: '', rrHour: '', rrState: '',
  };
}

const iso = (ms) => new Date(ms).toISOString();
const props = (ev) => ({ ...((ev && ev.extendedProperties && ev.extendedProperties.private) || {}) });
const sheetTimes = (ms) => ({ 'Review time (PH)': fmtSheet(ms), 'Review time (UTC)': iso(ms) });
const host = (ms) => `${fmtHost(ms)} Philippine time`;

// ---------------------------------------------------------------- rr-manage webhook

/**
 * First check of a change request, before Google is asked anything.
 * body: { key, action: 'look' | 'move' | 'cancel', slot? (ISO, for move) }
 */
function checkChange(body, nowMs, rules = RULES) {
  const b = body && typeof body === 'object' ? body : {};
  const key = String(b.key ?? '').trim();
  const action = String(b.action ?? '');
  if (!KEY_RE.test(key)) return { ok: false, status: 404, code: 'not_found' };
  if (!['look', 'move', 'cancel'].includes(action)) return { ok: false, status: 400, code: 'action' };
  if (action !== 'move') return { ok: true, key, action };
  const slot = String(b.slot ?? '').slice(0, 40);
  if (!isAllowedSlot(slot, nowMs, rules)) return { ok: false, status: 400, code: 'slot' };
  const startMs = Date.parse(slot);
  return { ok: true, key, action, start: iso(startMs), end: iso(startMs + rules.slotMinutes * MINUTE_MS) };
}

/**
 * Decide what to do, given the request (checkChange) and Google's answer to
 * events?privateExtendedProperty=rrKey=KEY. Returns what to answer, and for move/cancel what to change.
 */
function decideChange(req, list, nowMs, rules = CHANGE_RULES) {
  const no = (status, code) => ({ ok: false, status, code, respond: { ok: false, error: code } });
  const items = (list && Array.isArray(list.items)) ? list.items : [];
  const ev = items.find((e) => e && e.status !== 'cancelled' && props(e).rrKey === req.key && e.start && e.start.dateTime);
  if (!ev) return no(404, 'not_found');
  const p = props(ev);
  const startMs = Date.parse(ev.start.dateTime);
  const endMs = Date.parse((ev.end && ev.end.dateTime) || '') || startMs + 30 * MINUTE_MS;
  if (!(startMs > nowMs)) return no(410, 'started');
  const changes = Number(p.rrChanges) || 0;
  const left = Math.max(0, rules.maxChanges - changes);
  const name = p.rrName || '';
  const first = name.split(' ')[0] || '';
  const base = { eventId: ev.id, link: ev.htmlLink || '', email: p.rrEmail || '', from: iso(startMs) };

  if (req.action === 'look') {
    return { ok: true, status: 200, action: 'look', respond: { ok: true, start: iso(startMs), end: iso(endMs), name: first, changesLeft: left } };
  }

  const who = [`Name: ${name}`, `Email: ${p.rrEmail || ''}`, p.rrTz ? `Visitor's time zone: ${p.rrTz}` : ''].filter(Boolean);

  if (req.action === 'move') {
    if (left <= 0) return no(409, 'no_changes_left');
    const toMs = Date.parse(req.start);
    if (toMs === startMs) return no(400, 'same_time');
    return {
      ok: true, status: 200, action: 'move', ...base, to: iso(toMs),
      patch: {
        start: { dateTime: req.start }, end: { dateTime: req.end },
        extendedProperties: { private: { ...p, rrStart: iso(toMs), rrSet: String(nowMs), rrChanges: String(changes + 1), rrDay: '', rrHour: '', rrState: '' } },
      },
      sheet: { 'Calendar link': ev.htmlLink || '', ...sheetTimes(toMs), Status: 'Rescheduled' },
      notify: {
        subject: `Review moved: ${name}, now ${host(toMs)}`,
        text: [`${name} moved their free review using the change link.`, '', `From: ${host(startMs)}`, `To:   ${host(toMs)}`, '',
          ...who, '', 'The calendar event and their invite are updated. The Meet link stays the same.',
          `Changes used: ${changes + 1} of ${rules.maxChanges}.`].join('\n'),
      },
      respond: { ok: true, action: 'move', start: iso(toMs), end: req.end, changesLeft: left - 1 },
    };
  }

  // cancel
  return {
    ok: true, status: 200, action: 'cancel', ...base, to: null,
    sheet: { 'Calendar link': ev.htmlLink || '', Status: 'Cancelled' },
    notify: {
      subject: `Review cancelled: ${name}, ${host(startMs)}`,
      text: [`${name} cancelled their free review using the change link.`, '', `Was: ${host(startMs)}`, '', ...who, '',
        'The calendar event is cancelled and Google has told them. Their email can book again.'].join('\n'),
    },
    respond: { ok: true, action: 'cancel' },
  };
}

// ---------------------------------------------------------------- 10-minute sweep: reminders and keeping in step

/** "2026-11-24 09:00" (or with seconds) in Philippine time, as the sheet shows it. */
function parsePh(v) {
  const m = String(v ?? '').match(/(\d{4})-(\d{2})-(\d{2})[ T,]+(\d{1,2}):(\d{2})/);
  if (!m) return NaN;
  return Date.UTC(+m[1], +m[2] - 1, +m[3], +m[4] - 8, +m[5]);
}
function rowStart(row) {
  const utc = String(row['Review time (UTC)'] ?? '');
  if (/Z$|[+-]\d\d:\d\d$/.test(utc) && Number.isFinite(Date.parse(utc))) return Date.parse(utc);
  return parsePh(row['Review time (PH)']);
}

/**
 * @param {object} list   Google events.list for now .. now + LIST_DAYS (singleEvents), ALL events on the calendar
 * @param {object[]} rows the bookings sheet rows (header names as keys)
 * @param {number} nowMs
 * @returns {{items: object[], moves: {email, from, to}[]}}
 *   items: one per thing to do, with any of
 *     eventId + patch  (update the event's private details; done BEFORE the email so a reminder is never sent twice)
 *     email            ({to, subject, text})
 *     sheet            (row update, matched on 'Calendar link')
 *   moves: for the remembered bookings (to = null: cancelled)
 */
function sweepReminders(list, rows, nowMs) {
  if (!list || !Array.isArray(list.items)) throw new Error('Google Calendar list missing: ' + JSON.stringify(list).slice(0, 300));
  const complete = !list.nextPageToken;
  const events = list.items.filter((e) => e && e.status !== 'cancelled');
  const links = new Set(events.map((e) => e.htmlLink).filter(Boolean));
  const rowByLink = new Map((rows || []).filter((r) => r && r['Calendar link']).map((r) => [r['Calendar link'], r]));
  const items = [];
  const moves = [];

  for (const ev of events) {
    let p = props(ev);
    const row = rowByLink.get(ev.htmlLink);
    const tagged = p.rr === '1';
    // Bookings made before 20 Nov have no private details: adopt them from their sheet row (no change link).
    const legacy = !tagged && ev.summary === EVENT_TITLE && !!row;
    if (!tagged && !legacy) continue;
    if (!ev.start || !ev.start.dateTime) continue;
    const startMs = Date.parse(ev.start.dateTime);
    if (!(startMs > nowMs)) continue;
    const start = iso(startMs);
    let changed = false;
    let sheet = null;
    if (legacy) {
      const guest0 = (ev.attendees || []).find((a) => a && !a.organizer && !a.self) || {};
      const bookedAt = parsePh(row['Booked at (PH)']);
      p = {
        rr: '1', rrKey: '', rrName: row.Name || guest0.displayName || '', rrEmail: String(row.Email || guest0.email || '').toLowerCase(),
        rrTz: row['Visitor time zone'] || '', rrStart: start, rrSet: String(Number.isFinite(bookedAt) ? bookedAt : 0),
        rrChanges: '0', rrDay: '', rrHour: '', rrState: '',
      };
      changed = true;
    }

    const guest = (ev.attendees || []).find((a) => a && String(a.email || '').toLowerCase() === p.rrEmail);
    if (guest && guest.responseStatus === 'declined') {
      if (p.rrState !== 'declined') items.push({ eventId: ev.id, patch: { extendedProperties: { private: { ...p, rrState: 'declined' } } }, sheet: { 'Calendar link': ev.htmlLink, Status: 'Declined' } });
      else if (changed) items.push({ eventId: ev.id, patch: { extendedProperties: { private: p } } });
      continue; // no reminders for a declined invite
    }
    if (p.rrState === 'declined') { p.rrState = ''; changed = true; sheet = { 'Calendar link': ev.htmlLink, Status: 'Booked' }; }

    // Moved in Google Calendar (by Jeff, or by a change the sweep hasn't seen): follow the new time.
    if (Date.parse(p.rrStart) !== startMs) {
      moves.push({ email: p.rrEmail, from: p.rrStart, to: start });
      p = { ...p, rrStart: start, rrSet: String(nowMs) };
      changed = true;
      sheet = { 'Calendar link': ev.htmlLink, ...sheetTimes(startMs), Status: 'Rescheduled' };
    }

    // Reminders for the event's current time. The sweep runs every 10 minutes.
    let email = null;
    const ahead = startMs - nowMs;
    const data = { name: p.rrName, email: p.rrEmail, tz: p.rrTz, start, meet: ev.hangoutLink || '', key: p.rrKey };
    if (p.rrHour !== start && ahead <= HOUR_MS && ahead > 10 * MINUTE_MS) {
      email = reminderEmail('hour', data);
      p = { ...p, rrHour: start, rrDay: start };
    } else if (p.rrDay !== start && ahead <= 24 * HOUR_MS && ahead > 2 * HOUR_MS && startMs - (Number(p.rrSet) || 0) >= 24 * HOUR_MS + 5 * MINUTE_MS) {
      // Skipped when the booking (or the last move) was made less than a day ahead, as before.
      email = reminderEmail('day', data);
      p = { ...p, rrDay: start };
    }
    if (email && !p.rrEmail) email = null;
    if (changed || email) items.push({ eventId: ev.id, patch: { extendedProperties: { private: p } }, ...(email ? { email } : {}), ...(sheet ? { sheet } : {}) });
  }

  // Cancelled in Google Calendar: a sheet row still "Booked" or "Rescheduled" whose event is gone.
  // Only when Google's list is complete, so a short or failed read never marks real bookings as cancelled.
  if (complete) {
    for (const row of rows || []) {
      const link = row && row['Calendar link'];
      const t = row ? rowStart(row) : NaN;
      if (!link || !['Booked', 'Rescheduled'].includes(String(row.Status || '').trim())) continue;
      if (!(t > nowMs && t < nowMs + (LIST_DAYS - 1) * 24 * HOUR_MS) || links.has(link)) continue;
      items.push({ sheet: { 'Calendar link': link, Status: 'Cancelled' } });
      moves.push({ email: String(row.Email || '').toLowerCase(), from: iso(t), to: null });
    }
  }
  return { items, moves };
}

// Booking request checks, run inside the n8n workflow before anything touches the calendar.
// The pop-up validates too, but the webhook is public, so these checks are the real gate.
// Copied into n8n by tools/build_n8n.mjs together with slots.js and manage.js (the import lines are dropped there).

const BOOKING_LIMITS = {
  name: 80, email: 254, company: 120, process: 400, summary: 2000, tz: 64,
  perEmailUpcoming: 1,     // one upcoming review per email address
  perDay: 6,               // new bookings accepted in any 24 hours, across everyone
};

// The opening of the calendar invite the visitor receives. Update the link if the site moves to its own domain.
const INVITE_PREP = [
  'Bring one report or check your team keeps redoing. Live example: https://rework-rescue.vercel.app/#samples',
  'No files or prep needed. Please leave out anything confidential.',
  '',
  'Your details',
];

// 20 Nov 2026: each booking gets a private link to change or cancel it (src/booking/manage.js).
const CHANGE_LINE = 'Need a different time? Change or cancel here:';

const clean = (v, max) => String(v ?? '').replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/g, '').replace(/[ \t]+/g, ' ').trim().slice(0, max);
const EMAIL = /^[^\s@<>()[\]\\,;:"]+@[^\s@<>()[\]\\,;:"]+\.[^\s@<>()[\]\\,;:"]{2,}$/;

const fmtHost = (ms) => new Intl.DateTimeFormat('en-US', {
  timeZone: 'Asia/Manila', weekday: 'long', month: 'long', day: 'numeric', hour: 'numeric', minute: '2-digit',
}).format(new Date(ms));

/**
 * @param {object} body     the JSON the pop-up sent
 * @param {number} nowMs
 * @param {{email:string, slot:string, at:number}[]} history  bookings this workflow accepted before
 * @param {object} [rules]
 * @param {string} [key]  the change-link key (from the n8n Crypto node); a fallback key is made if it's missing
 * @returns {{ok:true, booking:object, event:object, notify:object} | {ok:false, status:number, code:string}}
 */
function checkBooking(body, nowMs, history = [], rules = RULES, key = '') {
  const b = body && typeof body === 'object' ? body : {};
  // Honeypot: a hidden field people never fill in. Pretend it worked so bots don't learn anything.
  if (clean(b.website, 200)) return { ok: false, status: 200, code: 'ok' };

  const name = clean(b.name, BOOKING_LIMITS.name + 1);
  const email = clean(b.email, BOOKING_LIMITS.email + 1).toLowerCase();
  const company = clean(b.company, BOOKING_LIMITS.company);
  const process = clean(b.process, BOOKING_LIMITS.process);
  const summary = String(b.summary ?? '').replace(/\r/g, '').trim().slice(0, BOOKING_LIMITS.summary);
  const tz = clean(b.tz, BOOKING_LIMITS.tz);
  const slot = clean(b.slot, 40);

  if (!name || name.length > BOOKING_LIMITS.name) return { ok: false, status: 400, code: 'name' };
  if (!EMAIL.test(email) || email.length > BOOKING_LIMITS.email) return { ok: false, status: 400, code: 'email' };
  if (!isAllowedSlot(slot, nowMs, rules)) return { ok: false, status: 400, code: 'slot' };

  const startMs = Date.parse(slot);
  const endMs = startMs + rules.slotMinutes * 60e3;
  const upcoming = history.filter((h) => h.email === email && Date.parse(h.slot) > nowMs);
  if (upcoming.length >= BOOKING_LIMITS.perEmailUpcoming) return { ok: false, status: 429, code: 'already_booked' };
  if (history.filter((h) => nowMs - h.at < 24 * 3600e3).length >= BOOKING_LIMITS.perDay) return { ok: false, status: 429, code: 'busy' };

  const start = new Date(startMs).toISOString();
  const end = new Date(endMs).toISOString();
  const whenHost = `${fmtHost(startMs)} Philippine time`;
  const changeKey = KEY_RE.test(String(key)) ? String(key) : newKey();
  const footer = '\nBooked through the Rework Rescue website.';
  const resultLine = summary ? `\nFind Your Rework result:\n${summary}` : '';

  // Invite: what the visitor sees. No time zone line; Google Calendar already shows their local time.
  const inviteLines = [
    `Name: ${name}`, `Email: ${email}`, company ? `Company: ${company}` : '',
    process ? `Report or process: ${process}` : '', resultLine, footer,
  ].filter(Boolean);

  // Notification: what Jeff sees. Keeps the visitor's time zone.
  const notifyLines = [
    `Name: ${name}`, `Email: ${email}`, company ? `Company: ${company}` : '',
    process ? `Report or process: ${process}` : '', tz ? `Visitor's time zone: ${tz}` : '',
    resultLine, footer,
  ].filter(Boolean);

  return {
    ok: true,
    booking: { name, email, company, process, summary, tz, start, end, key: changeKey },
    event: {
      summary: EVENT_TITLE,
      description: [...INVITE_PREP.slice(0, 2), `${CHANGE_LINE} ${changeLink(changeKey)}`, ...INVITE_PREP.slice(2), ...inviteLines].join('\n'),
      start: { dateTime: start },
      end: { dateTime: end },
      attendees: [{ email, displayName: name }],
      conferenceData: { createRequest: { requestId: `rr-${startMs}-${Math.random().toString(36).slice(2, 10)}`, conferenceSolutionKey: { type: 'hangoutsMeet' } } },
      reminders: { useDefault: true },
      // Private to Jeff's calendar: the change-link key and what the reminders need. Guests never see these.
      extendedProperties: { private: bookingProps({ key: changeKey, name, email, tz, start, nowMs }) },
    },
    notify: {
      subject: `New review booked: ${name}${company ? ` (${company})` : ''}, ${whenHost}`,
      text: [`New free review booked for ${whenHost}.`, '', ...notifyLines, '', 'The calendar invite with the Meet link has been sent to them.'].join('\n'),
    },
  };
}

/**
 * Clear remembered bookings so an email can book again (Jeff's reset link; doesn't touch the calendar or sheet).
 * `email` is one address (any case), or 'all' to clear the whole list.
 * @returns {{history:object[], removed:number}}
 */
function forgetBooking(history, email) {
  const list = history || [];
  const target = String(email ?? '').trim().toLowerCase();
  if (!target) return { history: list, removed: 0 };
  const kept = target === 'all' ? [] : list.filter((h) => h.email !== target);
  return { history: kept, removed: list.length - kept.length };
}

/**
 * Keep the remembered bookings in step after a change: `to` is the new start (ISO), or null when cancelled.
 * Only the entry for that email and old start changes.
 */
function moveBooking(history, { email, from, to }) {
  const target = String(email ?? '').trim().toLowerCase();
  const fromMs = Date.parse(from);
  const same = (h) => h.email === target && Date.parse(h.slot) === fromMs;
  const list = history || [];
  return to ? list.map((h) => (same(h) ? { ...h, slot: to } : h)) : list.filter((h) => !same(h));
}

/** Bookings worth remembering for the limits: drop entries more than a day old whose slot has passed. */
function pruneHistory(history, nowMs) {
  return (history || []).filter((h) => Date.parse(h.slot) > nowMs || nowMs - h.at < 24 * 3600e3);
}

// Google Sheet log: one row per booking. Create a sheet whose first row has exactly these headers.
const SHEET_COLUMNS = [
  'Booked at (PH)', 'Review time (PH)', 'Review time (UTC)', 'Name', 'Email', 'Company',
  'Report or process', 'Visitor time zone', 'Find Your Rework result', 'Meet link', 'Calendar link', 'Status',
];

const fmtSheet = (ms) => new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Asia/Manila', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false,
}).format(new Date(ms)).replace(',', '');

/** The sheet row for a booking that went through. Status starts as "Booked" for Jeff to update by hand. */
function sheetRow(booking, { meet = '', eventLink = '', nowMs = Date.now() } = {}) {
  // A leading = + - @ would make Sheets treat a visitor's text as a formula; prefix those with an apostrophe.
  const safe = (v) => { const s = String(v ?? ''); return /^[=+\-@]/.test(s) ? `'${s}` : s; };
  const values = [
    fmtSheet(nowMs), fmtSheet(Date.parse(booking.start)), booking.start, booking.name, booking.email, booking.company,
    booking.process, booking.tz, booking.summary, meet, eventLink, 'Booked',
  ];
  return Object.fromEntries(SHEET_COLUMNS.map((c, i) => [c, i < 3 ? values[i] : safe(values[i])]));
}

// ---------------------------------------------------------------- Reminder emails to the visitor
// Sent by the workflow 1 day and 1 hour before the review, in the visitor's own time zone.
const SITE_EXAMPLES = 'https://rework-rescue.vercel.app/#samples';

function visitorTime(ms, tz) {
  const opts = { weekday: 'long', month: 'long', day: 'numeric', hour: 'numeric', minute: '2-digit', timeZoneName: 'short' };
  try { return new Intl.DateTimeFormat('en-US', { ...opts, timeZone: tz || 'Asia/Manila' }).format(new Date(ms)); }
  catch { return new Intl.DateTimeFormat('en-US', { ...opts, timeZone: 'Asia/Manila' }).format(new Date(ms)); }
}

/**
 * The reminder emails, in the visitor's own time zone. kind: 'day' (1 day before) or 'hour' (1 hour before).
 * When the booking is sent by src/booking/manage.js (sweepReminders), which decides when each one is due.
 * key: the change-link key; without one (bookings made before 20 Nov) the email says to reply instead.
 */
function reminderEmail(kind, { name = '', email = '', tz = '', start, meet = '', key = '' }) {
  const startMs = Date.parse(start);
  const when = visitorTime(startMs, tz);
  const first = String(name || '').split(' ')[0] || 'there';
  const join = meet ? `Join with Google Meet: ${meet}` : 'The Google Meet link is in your calendar invite.';
  const sign = ['Jeff Herson Vida', 'Rework Rescue · Less rework. More real work.'];
  const link = KEY_RE.test(String(key)) ? changeLink(key) : '';
  if (kind === 'day') {
    return {
      to: email,
      subject: 'Reminder: your free review is tomorrow',
      text: [
        `Hi ${first},`, '',
        'A quick reminder of your free 30-minute review with me tomorrow:', when, join, '',
        `Before the call, have one report, check or workflow in mind that your team keeps redoing, like the examples on my site: ${SITE_EXAMPLES}`,
        'No preparation or files needed, and please leave out anything confidential.', '',
        link ? `${CHANGE_LINE} ${link}` : 'Need to change the time? Just reply to this email.', '', ...sign,
      ].join('\n'),
    };
  }
  return {
    to: email,
    subject: 'Starting in an hour: your free review',
    text: [
      `Hi ${first},`, '', `Your free review starts in an hour: ${when}.`, join, '',
      link ? `Can't make it? Change or cancel here: ${link}` : "Can't make it? Just reply to this email.", '',
      'See you soon,', ...sign,
    ].join('\n'),
  };
}

// ---- workflow step
return [{ json: checkChange($input.first().json.body, Date.now()) }];

// Booking slot rules: the ONE place that decides which times can be booked.
//
// Used in two places:
//  - the n8n workflow (copied into its Code nodes by tools/build_n8n.mjs), which checks Google Calendar
//    and returns only the free slots, and re-checks a slot before booking it;
//  - the booking pop-up (src/ui/booking.js), only as a fallback while n8n isn't connected.
//
// Change the hours here, run `node tools/build_n8n.mjs`, and re-import n8n/rework-review-booking.json.
// Keep this file free of imports and browser/Node-only APIs: it must run inside an n8n Code node.

const RULES = {
  hostOffsetHours: 8,          // Philippine time, UTC+8, no daylight saving
  days: [1, 2, 3, 4, 5],       // days a window STARTS on (0 = Sunday): Monday to Friday
  start: '08:00',              // first start time, Philippine time
  end: '02:00',                // window ends at this time; earlier than start means the next day (Fri 8:00 am to Sat 2:00 am)
  slotMinutes: 30,             // meeting length, and the step between start times
  minNoticeHours: 12,          // no bookings sooner than this
  daysAhead: 28,               // how far ahead people can book
};

const MIN = 60e3;

function toMinutes(hhmm) {
  const [h, m] = hhmm.split(':').map(Number);
  return h * 60 + m;
}

/** Every bookable start time (ms since epoch, UTC) from now, before checking the calendar. */
function candidateSlots(nowMs, rules = RULES) {
  const off = rules.hostOffsetHours * 60 * MIN;
  const startMin = toMinutes(rules.start);
  let endMin = toMinutes(rules.end);
  if (endMin <= startMin) endMin += 24 * 60;
  const earliest = nowMs + rules.minNoticeHours * 60 * MIN;
  const latest = nowMs + rules.daysAhead * 24 * 60 * MIN;

  // Host-local midnight of "today", as a UTC timestamp. Start one day back so a window that began
  // yesterday evening and runs past midnight is still included.
  const hostNow = new Date(nowMs + off);
  const todayMidnight = Date.UTC(hostNow.getUTCFullYear(), hostNow.getUTCMonth(), hostNow.getUTCDate()) - off;

  const out = [];
  for (let i = -1; i <= rules.daysAhead + 1; i++) {
    const dayStart = todayMidnight + i * 24 * 60 * MIN;
    const weekday = new Date(dayStart + off).getUTCDay();
    if (!rules.days.includes(weekday)) continue;
    for (let m = startMin; m + rules.slotMinutes <= endMin; m += rules.slotMinutes) {
      const t = dayStart + m * MIN;
      if (t >= earliest && t <= latest) out.push(t);
    }
  }
  return out;
}

/** Free start times: candidates that don't overlap any busy period ({start, end} ISO strings). */
function freeSlots(nowMs, busy = [], rules = RULES) {
  const periods = busy
    .map((b) => [Date.parse(b.start), Date.parse(b.end)])
    .filter(([s, e]) => Number.isFinite(s) && Number.isFinite(e));
  const len = rules.slotMinutes * MIN;
  return candidateSlots(nowMs, rules).filter((t) => !periods.some(([s, e]) => t < e && t + len > s));
}

/** True if this exact start time (ISO string) is one the rules allow. Does not check the calendar. */
function isAllowedSlot(iso, nowMs, rules = RULES) {
  const t = Date.parse(iso);
  if (!Number.isFinite(t)) return false;
  return candidateSlots(nowMs, rules).includes(t);
}

// Change or cancel a booking, and the reminder sweep. Run inside the n8n booking workflow (tools/build_n8n.mjs
// copies this file in with slots.js and check.js; import lines are dropped there). 20 Nov 2026, Jeff: automated.
//
// How it fits together
//  - Every booking's Google Calendar event carries private details (extendedProperties.private, visible only on
//    Jeff's calendar): a random key, the visitor's name, email and time zone, the start the workflow knows about,
//    how many times it was changed, and which reminders went out.
//  - The invite and reminders link to https://rework-rescue.vercel.app/#booking=KEY. The pop-up sends that key to
//    the rr-manage webhook to look the booking up, move it (same event, same Meet link) or cancel it.
//  - Every 10 minutes the workflow reads the calendar and the bookings sheet (sweepReminders): it sends reminders
//    that are due for the event's CURRENT time, notices when Jeff moved or cancelled a review in Google Calendar,
//    or the visitor declined the invite, and keeps the sheet in step.
//
// Keep this file free of browser/Node-only APIs: it must run inside an n8n Code node.

const CHANGE_RULES = {
  maxChanges: 2,            // a visitor can move one booking twice; after that, "reply to the invite"
  // New times follow the normal booking rules in slots.js (12 hours' notice, up to 28 days ahead).
  // Moving or cancelling is possible until the review starts.
};
const SITE_URL = 'https://rework-rescue.vercel.app/';
const EVENT_TITLE = 'Free review with Jeff (Rework Rescue)';
const KEY_RE = /^[A-Za-z0-9]{24,64}$/;
const LIST_DAYS = 60; // how far ahead the sweep reads the calendar (bookings go 28 days ahead)

const HOUR_MS = 3600e3;
const MINUTE_MS = 60e3;

/** The visitor's private link. A #fragment, so the key never reaches a server log or another site. */
const changeLink = (key) => `${SITE_URL}#booking=${key}`;

/** Fallback key if the n8n Crypto node didn't supply one (it normally does). */
function newKey(rand = Math.random) {
  const abc = 'abcdefghijklmnopqrstuvwxyz0123456789';
  let k = '';
  for (let i = 0; i < 32; i++) k += abc[Math.floor(rand() * abc.length) % abc.length];
  return k;
}

/** What a new booking keeps on its calendar event. Google needs every value as a string. */
function bookingProps({ key, name, email, tz, start, nowMs }) {
  return {
    rr: '1', rrKey: key, rrName: name, rrEmail: email, rrTz: tz || '', rrStart: new Date(Date.parse(start)).toISOString(),
    rrSet: String(nowMs), rrChanges: '0', rrDay: '', rrHour: '', rrState: '',
  };
}

const iso = (ms) => new Date(ms).toISOString();
const props = (ev) => ({ ...((ev && ev.extendedProperties && ev.extendedProperties.private) || {}) });
const sheetTimes = (ms) => ({ 'Review time (PH)': fmtSheet(ms), 'Review time (UTC)': iso(ms) });
const host = (ms) => `${fmtHost(ms)} Philippine time`;

// ---------------------------------------------------------------- rr-manage webhook

/**
 * First check of a change request, before Google is asked anything.
 * body: { key, action: 'look' | 'move' | 'cancel', slot? (ISO, for move) }
 */
function checkChange(body, nowMs, rules = RULES) {
  const b = body && typeof body === 'object' ? body : {};
  const key = String(b.key ?? '').trim();
  const action = String(b.action ?? '');
  if (!KEY_RE.test(key)) return { ok: false, status: 404, code: 'not_found' };
  if (!['look', 'move', 'cancel'].includes(action)) return { ok: false, status: 400, code: 'action' };
  if (action !== 'move') return { ok: true, key, action };
  const slot = String(b.slot ?? '').slice(0, 40);
  if (!isAllowedSlot(slot, nowMs, rules)) return { ok: false, status: 400, code: 'slot' };
  const startMs = Date.parse(slot);
  return { ok: true, key, action, start: iso(startMs), end: iso(startMs + rules.slotMinutes * MINUTE_MS) };
}

/**
 * Decide what to do, given the request (checkChange) and Google's answer to
 * events?privateExtendedProperty=rrKey=KEY. Returns what to answer, and for move/cancel what to change.
 */
function decideChange(req, list, nowMs, rules = CHANGE_RULES) {
  const no = (status, code) => ({ ok: false, status, code, respond: { ok: false, error: code } });
  const items = (list && Array.isArray(list.items)) ? list.items : [];
  const ev = items.find((e) => e && e.status !== 'cancelled' && props(e).rrKey === req.key && e.start && e.start.dateTime);
  if (!ev) return no(404, 'not_found');
  const p = props(ev);
  const startMs = Date.parse(ev.start.dateTime);
  const endMs = Date.parse((ev.end && ev.end.dateTime) || '') || startMs + 30 * MINUTE_MS;
  if (!(startMs > nowMs)) return no(410, 'started');
  const changes = Number(p.rrChanges) || 0;
  const left = Math.max(0, rules.maxChanges - changes);
  const name = p.rrName || '';
  const first = name.split(' ')[0] || '';
  const base = { eventId: ev.id, link: ev.htmlLink || '', email: p.rrEmail || '', from: iso(startMs) };

  if (req.action === 'look') {
    return { ok: true, status: 200, action: 'look', respond: { ok: true, start: iso(startMs), end: iso(endMs), name: first, changesLeft: left } };
  }

  const who = [`Name: ${name}`, `Email: ${p.rrEmail || ''}`, p.rrTz ? `Visitor's time zone: ${p.rrTz}` : ''].filter(Boolean);

  if (req.action === 'move') {
    if (left <= 0) return no(409, 'no_changes_left');
    const toMs = Date.parse(req.start);
    if (toMs === startMs) return no(400, 'same_time');
    return {
      ok: true, status: 200, action: 'move', ...base, to: iso(toMs),
      patch: {
        start: { dateTime: req.start }, end: { dateTime: req.end },
        extendedProperties: { private: { ...p, rrStart: iso(toMs), rrSet: String(nowMs), rrChanges: String(changes + 1), rrDay: '', rrHour: '', rrState: '' } },
      },
      sheet: { 'Calendar link': ev.htmlLink || '', ...sheetTimes(toMs), Status: 'Rescheduled' },
      notify: {
        subject: `Review moved: ${name}, now ${host(toMs)}`,
        text: [`${name} moved their free review using the change link.`, '', `From: ${host(startMs)}`, `To:   ${host(toMs)}`, '',
          ...who, '', 'The calendar event and their invite are updated. The Meet link stays the same.',
          `Changes used: ${changes + 1} of ${rules.maxChanges}.`].join('\n'),
      },
      respond: { ok: true, action: 'move', start: iso(toMs), end: req.end, changesLeft: left - 1 },
    };
  }

  // cancel
  return {
    ok: true, status: 200, action: 'cancel', ...base, to: null,
    sheet: { 'Calendar link': ev.htmlLink || '', Status: 'Cancelled' },
    notify: {
      subject: `Review cancelled: ${name}, ${host(startMs)}`,
      text: [`${name} cancelled their free review using the change link.`, '', `Was: ${host(startMs)}`, '', ...who, '',
        'The calendar event is cancelled and Google has told them. Their email can book again.'].join('\n'),
    },
    respond: { ok: true, action: 'cancel' },
  };
}

// ---------------------------------------------------------------- 10-minute sweep: reminders and keeping in step

/** "2026-11-24 09:00" (or with seconds) in Philippine time, as the sheet shows it. */
function parsePh(v) {
  const m = String(v ?? '').match(/(\d{4})-(\d{2})-(\d{2})[ T,]+(\d{1,2}):(\d{2})/);
  if (!m) return NaN;
  return Date.UTC(+m[1], +m[2] - 1, +m[3], +m[4] - 8, +m[5]);
}
function rowStart(row) {
  const utc = String(row['Review time (UTC)'] ?? '');
  if (/Z$|[+-]\d\d:\d\d$/.test(utc) && Number.isFinite(Date.parse(utc))) return Date.parse(utc);
  return parsePh(row['Review time (PH)']);
}

/**
 * @param {object} list   Google events.list for now .. now + LIST_DAYS (singleEvents), ALL events on the calendar
 * @param {object[]} rows the bookings sheet rows (header names as keys)
 * @param {number} nowMs
 * @returns {{items: object[], moves: {email, from, to}[]}}
 *   items: one per thing to do, with any of
 *     eventId + patch  (update the event's private details; done BEFORE the email so a reminder is never sent twice)
 *     email            ({to, subject, text})
 *     sheet            (row update, matched on 'Calendar link')
 *   moves: for the remembered bookings (to = null: cancelled)
 */
function sweepReminders(list, rows, nowMs) {
  if (!list || !Array.isArray(list.items)) throw new Error('Google Calendar list missing: ' + JSON.stringify(list).slice(0, 300));
  const complete = !list.nextPageToken;
  const events = list.items.filter((e) => e && e.status !== 'cancelled');
  const links = new Set(events.map((e) => e.htmlLink).filter(Boolean));
  const rowByLink = new Map((rows || []).filter((r) => r && r['Calendar link']).map((r) => [r['Calendar link'], r]));
  const items = [];
  const moves = [];

  for (const ev of events) {
    let p = props(ev);
    const row = rowByLink.get(ev.htmlLink);
    const tagged = p.rr === '1';
    // Bookings made before 20 Nov have no private details: adopt them from their sheet row (no change link).
    const legacy = !tagged && ev.summary === EVENT_TITLE && !!row;
    if (!tagged && !legacy) continue;
    if (!ev.start || !ev.start.dateTime) continue;
    const startMs = Date.parse(ev.start.dateTime);
    if (!(startMs > nowMs)) continue;
    const start = iso(startMs);
    let changed = false;
    let sheet = null;
    if (legacy) {
      const guest0 = (ev.attendees || []).find((a) => a && !a.organizer && !a.self) || {};
      const bookedAt = parsePh(row['Booked at (PH)']);
      p = {
        rr: '1', rrKey: '', rrName: row.Name || guest0.displayName || '', rrEmail: String(row.Email || guest0.email || '').toLowerCase(),
        rrTz: row['Visitor time zone'] || '', rrStart: start, rrSet: String(Number.isFinite(bookedAt) ? bookedAt : 0),
        rrChanges: '0', rrDay: '', rrHour: '', rrState: '',
      };
      changed = true;
    }

    const guest = (ev.attendees || []).find((a) => a && String(a.email || '').toLowerCase() === p.rrEmail);
    if (guest && guest.responseStatus === 'declined') {
      if (p.rrState !== 'declined') items.push({ eventId: ev.id, patch: { extendedProperties: { private: { ...p, rrState: 'declined' } } }, sheet: { 'Calendar link': ev.htmlLink, Status: 'Declined' } });
      else if (changed) items.push({ eventId: ev.id, patch: { extendedProperties: { private: p } } });
      continue; // no reminders for a declined invite
    }
    if (p.rrState === 'declined') { p.rrState = ''; changed = true; sheet = { 'Calendar link': ev.htmlLink, Status: 'Booked' }; }

    // Moved in Google Calendar (by Jeff, or by a change the sweep hasn't seen): follow the new time.
    if (Date.parse(p.rrStart) !== startMs) {
      moves.push({ email: p.rrEmail, from: p.rrStart, to: start });
      p = { ...p, rrStart: start, rrSet: String(nowMs) };
      changed = true;
      sheet = { 'Calendar link': ev.htmlLink, ...sheetTimes(startMs), Status: 'Rescheduled' };
    }

    // Reminders for the event's current time. The sweep runs every 10 minutes.
    let email = null;
    const ahead = startMs - nowMs;
    const data = { name: p.rrName, email: p.rrEmail, tz: p.rrTz, start, meet: ev.hangoutLink || '', key: p.rrKey };
    if (p.rrHour !== start && ahead <= HOUR_MS && ahead > 10 * MINUTE_MS) {
      email = reminderEmail('hour', data);
      p = { ...p, rrHour: start, rrDay: start };
    } else if (p.rrDay !== start && ahead <= 24 * HOUR_MS && ahead > 2 * HOUR_MS && startMs - (Number(p.rrSet) || 0) >= 24 * HOUR_MS + 5 * MINUTE_MS) {
      // Skipped when the booking (or the last move) was made less than a day ahead, as before.
      email = reminderEmail('day', data);
      p = { ...p, rrDay: start };
    }
    if (email && !p.rrEmail) email = null;
    if (changed || email) items.push({ eventId: ev.id, patch: { extendedProperties: { private: p } }, ...(email ? { email } : {}), ...(sheet ? { sheet } : {}) });
  }

  // Cancelled in Google Calendar: a sheet row still "Booked" or "Rescheduled" whose event is gone.
  // Only when Google's list is complete, so a short or failed read never marks real bookings as cancelled.
  if (complete) {
    for (const row of rows || []) {
      const link = row && row['Calendar link'];
      const t = row ? rowStart(row) : NaN;
      if (!link || !['Booked', 'Rescheduled'].includes(String(row.Status || '').trim())) continue;
      if (!(t > nowMs && t < nowMs + (LIST_DAYS - 1) * 24 * HOUR_MS) || links.has(link)) continue;
      items.push({ sheet: { 'Calendar link': link, Status: 'Cancelled' } });
      moves.push({ email: String(row.Email || '').toLowerCase(), from: iso(t), to: null });
    }
  }
  return { items, moves };
}

// Booking request checks, run inside the n8n workflow before anything touches the calendar.
// The pop-up validates too, but the webhook is public, so these checks are the real gate.
// Copied into n8n by tools/build_n8n.mjs together with slots.js and manage.js (the import lines are dropped there).

const BOOKING_LIMITS = {
  name: 80, email: 254, company: 120, process: 400, summary: 2000, tz: 64,
  perEmailUpcoming: 1,     // one upcoming review per email address
  perDay: 6,               // new bookings accepted in any 24 hours, across everyone
};

// The opening of the calendar invite the visitor receives. Update the link if the site moves to its own domain.
const INVITE_PREP = [
  'Bring one report or check your team keeps redoing. Live example: https://rework-rescue.vercel.app/#samples',
  'No files or prep needed. Please leave out anything confidential.',
  '',
  'Your details',
];

// 20 Nov 2026: each booking gets a private link to change or cancel it (src/booking/manage.js).
const CHANGE_LINE = 'Need a different time? Change or cancel here:';

const clean = (v, max) => String(v ?? '').replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/g, '').replace(/[ \t]+/g, ' ').trim().slice(0, max);
const EMAIL = /^[^\s@<>()[\]\\,;:"]+@[^\s@<>()[\]\\,;:"]+\.[^\s@<>()[\]\\,;:"]{2,}$/;

const fmtHost = (ms) => new Intl.DateTimeFormat('en-US', {
  timeZone: 'Asia/Manila', weekday: 'long', month: 'long', day: 'numeric', hour: 'numeric', minute: '2-digit',
}).format(new Date(ms));

/**
 * @param {object} body     the JSON the pop-up sent
 * @param {number} nowMs
 * @param {{email:string, slot:string, at:number}[]} history  bookings this workflow accepted before
 * @param {object} [rules]
 * @param {string} [key]  the change-link key (from the n8n Crypto node); a fallback key is made if it's missing
 * @returns {{ok:true, booking:object, event:object, notify:object} | {ok:false, status:number, code:string}}
 */
function checkBooking(body, nowMs, history = [], rules = RULES, key = '') {
  const b = body && typeof body === 'object' ? body : {};
  // Honeypot: a hidden field people never fill in. Pretend it worked so bots don't learn anything.
  if (clean(b.website, 200)) return { ok: false, status: 200, code: 'ok' };

  const name = clean(b.name, BOOKING_LIMITS.name + 1);
  const email = clean(b.email, BOOKING_LIMITS.email + 1).toLowerCase();
  const company = clean(b.company, BOOKING_LIMITS.company);
  const process = clean(b.process, BOOKING_LIMITS.process);
  const summary = String(b.summary ?? '').replace(/\r/g, '').trim().slice(0, BOOKING_LIMITS.summary);
  const tz = clean(b.tz, BOOKING_LIMITS.tz);
  const slot = clean(b.slot, 40);

  if (!name || name.length > BOOKING_LIMITS.name) return { ok: false, status: 400, code: 'name' };
  if (!EMAIL.test(email) || email.length > BOOKING_LIMITS.email) return { ok: false, status: 400, code: 'email' };
  if (!isAllowedSlot(slot, nowMs, rules)) return { ok: false, status: 400, code: 'slot' };

  const startMs = Date.parse(slot);
  const endMs = startMs + rules.slotMinutes * 60e3;
  const upcoming = history.filter((h) => h.email === email && Date.parse(h.slot) > nowMs);
  if (upcoming.length >= BOOKING_LIMITS.perEmailUpcoming) return { ok: false, status: 429, code: 'already_booked' };
  if (history.filter((h) => nowMs - h.at < 24 * 3600e3).length >= BOOKING_LIMITS.perDay) return { ok: false, status: 429, code: 'busy' };

  const start = new Date(startMs).toISOString();
  const end = new Date(endMs).toISOString();
  const whenHost = `${fmtHost(startMs)} Philippine time`;
  const changeKey = KEY_RE.test(String(key)) ? String(key) : newKey();
  const footer = '\nBooked through the Rework Rescue website.';
  const resultLine = summary ? `\nFind Your Rework result:\n${summary}` : '';

  // Invite: what the visitor sees. No time zone line; Google Calendar already shows their local time.
  const inviteLines = [
    `Name: ${name}`, `Email: ${email}`, company ? `Company: ${company}` : '',
    process ? `Report or process: ${process}` : '', resultLine, footer,
  ].filter(Boolean);

  // Notification: what Jeff sees. Keeps the visitor's time zone.
  const notifyLines = [
    `Name: ${name}`, `Email: ${email}`, company ? `Company: ${company}` : '',
    process ? `Report or process: ${process}` : '', tz ? `Visitor's time zone: ${tz}` : '',
    resultLine, footer,
  ].filter(Boolean);

  return {
    ok: true,
    booking: { name, email, company, process, summary, tz, start, end, key: changeKey },
    event: {
      summary: EVENT_TITLE,
      description: [...INVITE_PREP.slice(0, 2), `${CHANGE_LINE} ${changeLink(changeKey)}`, ...INVITE_PREP.slice(2), ...inviteLines].join('\n'),
      start: { dateTime: start },
      end: { dateTime: end },
      attendees: [{ email, displayName: name }],
      conferenceData: { createRequest: { requestId: `rr-${startMs}-${Math.random().toString(36).slice(2, 10)}`, conferenceSolutionKey: { type: 'hangoutsMeet' } } },
      reminders: { useDefault: true },
      // Private to Jeff's calendar: the change-link key and what the reminders need. Guests never see these.
      extendedProperties: { private: bookingProps({ key: changeKey, name, email, tz, start, nowMs }) },
    },
    notify: {
      subject: `New review booked: ${name}${company ? ` (${company})` : ''}, ${whenHost}`,
      text: [`New free review booked for ${whenHost}.`, '', ...notifyLines, '', 'The calendar invite with the Meet link has been sent to them.'].join('\n'),
    },
  };
}

/**
 * Clear remembered bookings so an email can book again (Jeff's reset link; doesn't touch the calendar or sheet).
 * `email` is one address (any case), or 'all' to clear the whole list.
 * @returns {{history:object[], removed:number}}
 */
function forgetBooking(history, email) {
  const list = history || [];
  const target = String(email ?? '').trim().toLowerCase();
  if (!target) return { history: list, removed: 0 };
  const kept = target === 'all' ? [] : list.filter((h) => h.email !== target);
  return { history: kept, removed: list.length - kept.length };
}

/**
 * Keep the remembered bookings in step after a change: `to` is the new start (ISO), or null when cancelled.
 * Only the entry for that email and old start changes.
 */
function moveBooking(history, { email, from, to }) {
  const target = String(email ?? '').trim().toLowerCase();
  const fromMs = Date.parse(from);
  const same = (h) => h.email === target && Date.parse(h.slot) === fromMs;
  const list = history || [];
  return to ? list.map((h) => (same(h) ? { ...h, slot: to } : h)) : list.filter((h) => !same(h));
}

/** Bookings worth remembering for the limits: drop entries more than a day old whose slot has passed. */
function pruneHistory(history, nowMs) {
  return (history || []).filter((h) => Date.parse(h.slot) > nowMs || nowMs - h.at < 24 * 3600e3);
}

// Google Sheet log: one row per booking. Create a sheet whose first row has exactly these headers.
const SHEET_COLUMNS = [
  'Booked at (PH)', 'Review time (PH)', 'Review time (UTC)', 'Name', 'Email', 'Company',
  'Report or process', 'Visitor time zone', 'Find Your Rework result', 'Meet link', 'Calendar link', 'Status',
];

const fmtSheet = (ms) => new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Asia/Manila', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false,
}).format(new Date(ms)).replace(',', '');

/** The sheet row for a booking that went through. Status starts as "Booked" for Jeff to update by hand. */
function sheetRow(booking, { meet = '', eventLink = '', nowMs = Date.now() } = {}) {
  // A leading = + - @ would make Sheets treat a visitor's text as a formula; prefix those with an apostrophe.
  const safe = (v) => { const s = String(v ?? ''); return /^[=+\-@]/.test(s) ? `'${s}` : s; };
  const values = [
    fmtSheet(nowMs), fmtSheet(Date.parse(booking.start)), booking.start, booking.name, booking.email, booking.company,
    booking.process, booking.tz, booking.summary, meet, eventLink, 'Booked',
  ];
  return Object.fromEntries(SHEET_COLUMNS.map((c, i) => [c, i < 3 ? values[i] : safe(values[i])]));
}

// ---------------------------------------------------------------- Reminder emails to the visitor
// Sent by the workflow 1 day and 1 hour before the review, in the visitor's own time zone.
const SITE_EXAMPLES = 'https://rework-rescue.vercel.app/#samples';

function visitorTime(ms, tz) {
  const opts = { weekday: 'long', month: 'long', day: 'numeric', hour: 'numeric', minute: '2-digit', timeZoneName: 'short' };
  try { return new Intl.DateTimeFormat('en-US', { ...opts, timeZone: tz || 'Asia/Manila' }).format(new Date(ms)); }
  catch { return new Intl.DateTimeFormat('en-US', { ...opts, timeZone: 'Asia/Manila' }).format(new Date(ms)); }
}

/**
 * The reminder emails, in the visitor's own time zone. kind: 'day' (1 day before) or 'hour' (1 hour before).
 * When the booking is sent by src/booking/manage.js (sweepReminders), which decides when each one is due.
 * key: the change-link key; without one (bookings made before 20 Nov) the email says to reply instead.
 */
function reminderEmail(kind, { name = '', email = '', tz = '', start, meet = '', key = '' }) {
  const startMs = Date.parse(start);
  const when = visitorTime(startMs, tz);
  const first = String(name || '').split(' ')[0] || 'there';
  const join = meet ? `Join with Google Meet: ${meet}` : 'The Google Meet link is in your calendar invite.';
  const sign = ['Jeff Herson Vida', 'Rework Rescue · Less rework. More real work.'];
  const link = KEY_RE.test(String(key)) ? changeLink(key) : '';
  if (kind === 'day') {
    return {
      to: email,
      subject: 'Reminder: your free review is tomorrow',
      text: [
        `Hi ${first},`, '',
        'A quick reminder of your free 30-minute review with me tomorrow:', when, join, '',
        `Before the call, have one report, check or workflow in mind that your team keeps redoing, like the examples on my site: ${SITE_EXAMPLES}`,
        'No preparation or files needed, and please leave out anything confidential.', '',
        link ? `${CHANGE_LINE} ${link}` : 'Need to change the time? Just reply to this email.', '', ...sign,
      ].join('\n'),
    };
  }
  return {
    to: email,
    subject: 'Starting in an hour: your free review',
    text: [
      `Hi ${first},`, '', `Your free review starts in an hour: ${when}.`, join, '',
      link ? `Can't make it? Change or cancel here: ${link}` : "Can't make it? Just reply to this email.", '',
      'See you soon,', ...sign,
    ].join('\n'),
  };
}

// ---- workflow step
return [{ json: decideChange($('Check the change request').first().json, $input.first().json, Date.now()) }];

// Booking slot rules: the ONE place that decides which times can be booked.
//
// Used in two places:
//  - the n8n workflow (copied into its Code nodes by tools/build_n8n.mjs), which checks Google Calendar
//    and returns only the free slots, and re-checks a slot before booking it;
//  - the booking pop-up (src/ui/booking.js), only as a fallback while n8n isn't connected.
//
// Change the hours here, run `node tools/build_n8n.mjs`, and re-import n8n/rework-review-booking.json.
// Keep this file free of imports and browser/Node-only APIs: it must run inside an n8n Code node.

const RULES = {
  hostOffsetHours: 8,          // Philippine time, UTC+8, no daylight saving
  days: [1, 2, 3, 4, 5],       // days a window STARTS on (0 = Sunday): Monday to Friday
  start: '08:00',              // first start time, Philippine time
  end: '02:00',                // window ends at this time; earlier than start means the next day (Fri 8:00 am to Sat 2:00 am)
  slotMinutes: 30,             // meeting length, and the step between start times
  minNoticeHours: 12,          // no bookings sooner than this
  daysAhead: 28,               // how far ahead people can book
};

const MIN = 60e3;

function toMinutes(hhmm) {
  const [h, m] = hhmm.split(':').map(Number);
  return h * 60 + m;
}

/** Every bookable start time (ms since epoch, UTC) from now, before checking the calendar. */
function candidateSlots(nowMs, rules = RULES) {
  const off = rules.hostOffsetHours * 60 * MIN;
  const startMin = toMinutes(rules.start);
  let endMin = toMinutes(rules.end);
  if (endMin <= startMin) endMin += 24 * 60;
  const earliest = nowMs + rules.minNoticeHours * 60 * MIN;
  const latest = nowMs + rules.daysAhead * 24 * 60 * MIN;

  // Host-local midnight of "today", as a UTC timestamp. Start one day back so a window that began
  // yesterday evening and runs past midnight is still included.
  const hostNow = new Date(nowMs + off);
  const todayMidnight = Date.UTC(hostNow.getUTCFullYear(), hostNow.getUTCMonth(), hostNow.getUTCDate()) - off;

  const out = [];
  for (let i = -1; i <= rules.daysAhead + 1; i++) {
    const dayStart = todayMidnight + i * 24 * 60 * MIN;
    const weekday = new Date(dayStart + off).getUTCDay();
    if (!rules.days.includes(weekday)) continue;
    for (let m = startMin; m + rules.slotMinutes <= endMin; m += rules.slotMinutes) {
      const t = dayStart + m * MIN;
      if (t >= earliest && t <= latest) out.push(t);
    }
  }
  return out;
}

/** Free start times: candidates that don't overlap any busy period ({start, end} ISO strings). */
function freeSlots(nowMs, busy = [], rules = RULES) {
  const periods = busy
    .map((b) => [Date.parse(b.start), Date.parse(b.end)])
    .filter(([s, e]) => Number.isFinite(s) && Number.isFinite(e));
  const len = rules.slotMinutes * MIN;
  return candidateSlots(nowMs, rules).filter((t) => !periods.some(([s, e]) => t < e && t + len > s));
}

/** True if this exact start time (ISO string) is one the rules allow. Does not check the calendar. */
function isAllowedSlot(iso, nowMs, rules = RULES) {
  const t = Date.parse(iso);
  if (!Number.isFinite(t)) return false;
  return candidateSlots(nowMs, rules).includes(t);
}

// Change or cancel a booking, and the reminder sweep. Run inside the n8n booking workflow (tools/build_n8n.mjs
// copies this file in with slots.js and check.js; import lines are dropped there). 20 Nov 2026, Jeff: automated.
//
// How it fits together
//  - Every booking's Google Calendar event carries private details (extendedProperties.private, visible only on
//    Jeff's calendar): a random key, the visitor's name, email and time zone, the start the workflow knows about,
//    how many times it was changed, and which reminders went out.
//  - The invite and reminders link to https://rework-rescue.vercel.app/#booking=KEY. The pop-up sends that key to
//    the rr-manage webhook to look the booking up, move it (same event, same Meet link) or cancel it.
//  - Every 10 minutes the workflow reads the calendar and the bookings sheet (sweepReminders): it sends reminders
//    that are due for the event's CURRENT time, notices when Jeff moved or cancelled a review in Google Calendar,
//    or the visitor declined the invite, and keeps the sheet in step.
//
// Keep this file free of browser/Node-only APIs: it must run inside an n8n Code node.

const CHANGE_RULES = {
  maxChanges: 2,            // a visitor can move one booking twice; after that, "reply to the invite"
  // New times follow the normal booking rules in slots.js (12 hours' notice, up to 28 days ahead).
  // Moving or cancelling is possible until the review starts.
};
const SITE_URL = 'https://rework-rescue.vercel.app/';
const EVENT_TITLE = 'Free review with Jeff (Rework Rescue)';
const KEY_RE = /^[A-Za-z0-9]{24,64}$/;
const LIST_DAYS = 60; // how far ahead the sweep reads the calendar (bookings go 28 days ahead)

const HOUR_MS = 3600e3;
const MINUTE_MS = 60e3;

/** The visitor's private link. A #fragment, so the key never reaches a server log or another site. */
const changeLink = (key) => `${SITE_URL}#booking=${key}`;

/** Fallback key if the n8n Crypto node didn't supply one (it normally does). */
function newKey(rand = Math.random) {
  const abc = 'abcdefghijklmnopqrstuvwxyz0123456789';
  let k = '';
  for (let i = 0; i < 32; i++) k += abc[Math.floor(rand() * abc.length) % abc.length];
  return k;
}

/** What a new booking keeps on its calendar event. Google needs every value as a string. */
function bookingProps({ key, name, email, tz, start, nowMs }) {
  return {
    rr: '1', rrKey: key, rrName: name, rrEmail: email, rrTz: tz || '', rrStart: new Date(Date.parse(start)).toISOString(),
    rrSet: String(nowMs), rrChanges: '0', rrDay: '', rrHour: '', rrState: '',
  };
}

const iso = (ms) => new Date(ms).toISOString();
const props = (ev) => ({ ...((ev && ev.extendedProperties && ev.extendedProperties.private) || {}) });
const sheetTimes = (ms) => ({ 'Review time (PH)': fmtSheet(ms), 'Review time (UTC)': iso(ms) });
const host = (ms) => `${fmtHost(ms)} Philippine time`;

// ---------------------------------------------------------------- rr-manage webhook

/**
 * First check of a change request, before Google is asked anything.
 * body: { key, action: 'look' | 'move' | 'cancel', slot? (ISO, for move) }
 */
function checkChange(body, nowMs, rules = RULES) {
  const b = body && typeof body === 'object' ? body : {};
  const key = String(b.key ?? '').trim();
  const action = String(b.action ?? '');
  if (!KEY_RE.test(key)) return { ok: false, status: 404, code: 'not_found' };
  if (!['look', 'move', 'cancel'].includes(action)) return { ok: false, status: 400, code: 'action' };
  if (action !== 'move') return { ok: true, key, action };
  const slot = String(b.slot ?? '').slice(0, 40);
  if (!isAllowedSlot(slot, nowMs, rules)) return { ok: false, status: 400, code: 'slot' };
  const startMs = Date.parse(slot);
  return { ok: true, key, action, start: iso(startMs), end: iso(startMs + rules.slotMinutes * MINUTE_MS) };
}

/**
 * Decide what to do, given the request (checkChange) and Google's answer to
 * events?privateExtendedProperty=rrKey=KEY. Returns what to answer, and for move/cancel what to change.
 */
function decideChange(req, list, nowMs, rules = CHANGE_RULES) {
  const no = (status, code) => ({ ok: false, status, code, respond: { ok: false, error: code } });
  const items = (list && Array.isArray(list.items)) ? list.items : [];
  const ev = items.find((e) => e && e.status !== 'cancelled' && props(e).rrKey === req.key && e.start && e.start.dateTime);
  if (!ev) return no(404, 'not_found');
  const p = props(ev);
  const startMs = Date.parse(ev.start.dateTime);
  const endMs = Date.parse((ev.end && ev.end.dateTime) || '') || startMs + 30 * MINUTE_MS;
  if (!(startMs > nowMs)) return no(410, 'started');
  const changes = Number(p.rrChanges) || 0;
  const left = Math.max(0, rules.maxChanges - changes);
  const name = p.rrName || '';
  const first = name.split(' ')[0] || '';
  const base = { eventId: ev.id, link: ev.htmlLink || '', email: p.rrEmail || '', from: iso(startMs) };

  if (req.action === 'look') {
    return { ok: true, status: 200, action: 'look', respond: { ok: true, start: iso(startMs), end: iso(endMs), name: first, changesLeft: left } };
  }

  const who = [`Name: ${name}`, `Email: ${p.rrEmail || ''}`, p.rrTz ? `Visitor's time zone: ${p.rrTz}` : ''].filter(Boolean);

  if (req.action === 'move') {
    if (left <= 0) return no(409, 'no_changes_left');
    const toMs = Date.parse(req.start);
    if (toMs === startMs) return no(400, 'same_time');
    return {
      ok: true, status: 200, action: 'move', ...base, to: iso(toMs),
      patch: {
        start: { dateTime: req.start }, end: { dateTime: req.end },
        extendedProperties: { private: { ...p, rrStart: iso(toMs), rrSet: String(nowMs), rrChanges: String(changes + 1), rrDay: '', rrHour: '', rrState: '' } },
      },
      sheet: { 'Calendar link': ev.htmlLink || '', ...sheetTimes(toMs), Status: 'Rescheduled' },
      notify: {
        subject: `Review moved: ${name}, now ${host(toMs)}`,
        text: [`${name} moved their free review using the change link.`, '', `From: ${host(startMs)}`, `To:   ${host(toMs)}`, '',
          ...who, '', 'The calendar event and their invite are updated. The Meet link stays the same.',
          `Changes used: ${changes + 1} of ${rules.maxChanges}.`].join('\n'),
      },
      respond: { ok: true, action: 'move', start: iso(toMs), end: req.end, changesLeft: left - 1 },
    };
  }

  // cancel
  return {
    ok: true, status: 200, action: 'cancel', ...base, to: null,
    sheet: { 'Calendar link': ev.htmlLink || '', Status: 'Cancelled' },
    notify: {
      subject: `Review cancelled: ${name}, ${host(startMs)}`,
      text: [`${name} cancelled their free review using the change link.`, '', `Was: ${host(startMs)}`, '', ...who, '',
        'The calendar event is cancelled and Google has told them. Their email can book again.'].join('\n'),
    },
    respond: { ok: true, action: 'cancel' },
  };
}

// ---------------------------------------------------------------- 10-minute sweep: reminders and keeping in step

/** "2026-11-24 09:00" (or with seconds) in Philippine time, as the sheet shows it. */
function parsePh(v) {
  const m = String(v ?? '').match(/(\d{4})-(\d{2})-(\d{2})[ T,]+(\d{1,2}):(\d{2})/);
  if (!m) return NaN;
  return Date.UTC(+m[1], +m[2] - 1, +m[3], +m[4] - 8, +m[5]);
}
function rowStart(row) {
  const utc = String(row['Review time (UTC)'] ?? '');
  if (/Z$|[+-]\d\d:\d\d$/.test(utc) && Number.isFinite(Date.parse(utc))) return Date.parse(utc);
  return parsePh(row['Review time (PH)']);
}

/**
 * @param {object} list   Google events.list for now .. now + LIST_DAYS (singleEvents), ALL events on the calendar
 * @param {object[]} rows the bookings sheet rows (header names as keys)
 * @param {number} nowMs
 * @returns {{items: object[], moves: {email, from, to}[]}}
 *   items: one per thing to do, with any of
 *     eventId + patch  (update the event's private details; done BEFORE the email so a reminder is never sent twice)
 *     email            ({to, subject, text})
 *     sheet            (row update, matched on 'Calendar link')
 *   moves: for the remembered bookings (to = null: cancelled)
 */
function sweepReminders(list, rows, nowMs) {
  if (!list || !Array.isArray(list.items)) throw new Error('Google Calendar list missing: ' + JSON.stringify(list).slice(0, 300));
  const complete = !list.nextPageToken;
  const events = list.items.filter((e) => e && e.status !== 'cancelled');
  const links = new Set(events.map((e) => e.htmlLink).filter(Boolean));
  const rowByLink = new Map((rows || []).filter((r) => r && r['Calendar link']).map((r) => [r['Calendar link'], r]));
  const items = [];
  const moves = [];

  for (const ev of events) {
    let p = props(ev);
    const row = rowByLink.get(ev.htmlLink);
    const tagged = p.rr === '1';
    // Bookings made before 20 Nov have no private details: adopt them from their sheet row (no change link).
    const legacy = !tagged && ev.summary === EVENT_TITLE && !!row;
    if (!tagged && !legacy) continue;
    if (!ev.start || !ev.start.dateTime) continue;
    const startMs = Date.parse(ev.start.dateTime);
    if (!(startMs > nowMs)) continue;
    const start = iso(startMs);
    let changed = false;
    let sheet = null;
    if (legacy) {
      const guest0 = (ev.attendees || []).find((a) => a && !a.organizer && !a.self) || {};
      const bookedAt = parsePh(row['Booked at (PH)']);
      p = {
        rr: '1', rrKey: '', rrName: row.Name || guest0.displayName || '', rrEmail: String(row.Email || guest0.email || '').toLowerCase(),
        rrTz: row['Visitor time zone'] || '', rrStart: start, rrSet: String(Number.isFinite(bookedAt) ? bookedAt : 0),
        rrChanges: '0', rrDay: '', rrHour: '', rrState: '',
      };
      changed = true;
    }

    const guest = (ev.attendees || []).find((a) => a && String(a.email || '').toLowerCase() === p.rrEmail);
    if (guest && guest.responseStatus === 'declined') {
      if (p.rrState !== 'declined') items.push({ eventId: ev.id, patch: { extendedProperties: { private: { ...p, rrState: 'declined' } } }, sheet: { 'Calendar link': ev.htmlLink, Status: 'Declined' } });
      else if (changed) items.push({ eventId: ev.id, patch: { extendedProperties: { private: p } } });
      continue; // no reminders for a declined invite
    }
    if (p.rrState === 'declined') { p.rrState = ''; changed = true; sheet = { 'Calendar link': ev.htmlLink, Status: 'Booked' }; }

    // Moved in Google Calendar (by Jeff, or by a change the sweep hasn't seen): follow the new time.
    if (Date.parse(p.rrStart) !== startMs) {
      moves.push({ email: p.rrEmail, from: p.rrStart, to: start });
      p = { ...p, rrStart: start, rrSet: String(nowMs) };
      changed = true;
      sheet = { 'Calendar link': ev.htmlLink, ...sheetTimes(startMs), Status: 'Rescheduled' };
    }

    // Reminders for the event's current time. The sweep runs every 10 minutes.
    let email = null;
    const ahead = startMs - nowMs;
    const data = { name: p.rrName, email: p.rrEmail, tz: p.rrTz, start, meet: ev.hangoutLink || '', key: p.rrKey };
    if (p.rrHour !== start && ahead <= HOUR_MS && ahead > 10 * MINUTE_MS) {
      email = reminderEmail('hour', data);
      p = { ...p, rrHour: start, rrDay: start };
    } else if (p.rrDay !== start && ahead <= 24 * HOUR_MS && ahead > 2 * HOUR_MS && startMs - (Number(p.rrSet) || 0) >= 24 * HOUR_MS + 5 * MINUTE_MS) {
      // Skipped when the booking (or the last move) was made less than a day ahead, as before.
      email = reminderEmail('day', data);
      p = { ...p, rrDay: start };
    }
    if (email && !p.rrEmail) email = null;
    if (changed || email) items.push({ eventId: ev.id, patch: { extendedProperties: { private: p } }, ...(email ? { email } : {}), ...(sheet ? { sheet } : {}) });
  }

  // Cancelled in Google Calendar: a sheet row still "Booked" or "Rescheduled" whose event is gone.
  // Only when Google's list is complete, so a short or failed read never marks real bookings as cancelled.
  if (complete) {
    for (const row of rows || []) {
      const link = row && row['Calendar link'];
      const t = row ? rowStart(row) : NaN;
      if (!link || !['Booked', 'Rescheduled'].includes(String(row.Status || '').trim())) continue;
      if (!(t > nowMs && t < nowMs + (LIST_DAYS - 1) * 24 * HOUR_MS) || links.has(link)) continue;
      items.push({ sheet: { 'Calendar link': link, Status: 'Cancelled' } });
      moves.push({ email: String(row.Email || '').toLowerCase(), from: iso(t), to: null });
    }
  }
  return { items, moves };
}

// Booking request checks, run inside the n8n workflow before anything touches the calendar.
// The pop-up validates too, but the webhook is public, so these checks are the real gate.
// Copied into n8n by tools/build_n8n.mjs together with slots.js and manage.js (the import lines are dropped there).

const BOOKING_LIMITS = {
  name: 80, email: 254, company: 120, process: 400, summary: 2000, tz: 64,
  perEmailUpcoming: 1,     // one upcoming review per email address
  perDay: 6,               // new bookings accepted in any 24 hours, across everyone
};

// The opening of the calendar invite the visitor receives. Update the link if the site moves to its own domain.
const INVITE_PREP = [
  'Bring one report or check your team keeps redoing. Live example: https://rework-rescue.vercel.app/#samples',
  'No files or prep needed. Please leave out anything confidential.',
  '',
  'Your details',
];

// 20 Nov 2026: each booking gets a private link to change or cancel it (src/booking/manage.js).
const CHANGE_LINE = 'Need a different time? Change or cancel here:';

const clean = (v, max) => String(v ?? '').replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/g, '').replace(/[ \t]+/g, ' ').trim().slice(0, max);
const EMAIL = /^[^\s@<>()[\]\\,;:"]+@[^\s@<>()[\]\\,;:"]+\.[^\s@<>()[\]\\,;:"]{2,}$/;

const fmtHost = (ms) => new Intl.DateTimeFormat('en-US', {
  timeZone: 'Asia/Manila', weekday: 'long', month: 'long', day: 'numeric', hour: 'numeric', minute: '2-digit',
}).format(new Date(ms));

/**
 * @param {object} body     the JSON the pop-up sent
 * @param {number} nowMs
 * @param {{email:string, slot:string, at:number}[]} history  bookings this workflow accepted before
 * @param {object} [rules]
 * @param {string} [key]  the change-link key (from the n8n Crypto node); a fallback key is made if it's missing
 * @returns {{ok:true, booking:object, event:object, notify:object} | {ok:false, status:number, code:string}}
 */
function checkBooking(body, nowMs, history = [], rules = RULES, key = '') {
  const b = body && typeof body === 'object' ? body : {};
  // Honeypot: a hidden field people never fill in. Pretend it worked so bots don't learn anything.
  if (clean(b.website, 200)) return { ok: false, status: 200, code: 'ok' };

  const name = clean(b.name, BOOKING_LIMITS.name + 1);
  const email = clean(b.email, BOOKING_LIMITS.email + 1).toLowerCase();
  const company = clean(b.company, BOOKING_LIMITS.company);
  const process = clean(b.process, BOOKING_LIMITS.process);
  const summary = String(b.summary ?? '').replace(/\r/g, '').trim().slice(0, BOOKING_LIMITS.summary);
  const tz = clean(b.tz, BOOKING_LIMITS.tz);
  const slot = clean(b.slot, 40);

  if (!name || name.length > BOOKING_LIMITS.name) return { ok: false, status: 400, code: 'name' };
  if (!EMAIL.test(email) || email.length > BOOKING_LIMITS.email) return { ok: false, status: 400, code: 'email' };
  if (!isAllowedSlot(slot, nowMs, rules)) return { ok: false, status: 400, code: 'slot' };

  const startMs = Date.parse(slot);
  const endMs = startMs + rules.slotMinutes * 60e3;
  const upcoming = history.filter((h) => h.email === email && Date.parse(h.slot) > nowMs);
  if (upcoming.length >= BOOKING_LIMITS.perEmailUpcoming) return { ok: false, status: 429, code: 'already_booked' };
  if (history.filter((h) => nowMs - h.at < 24 * 3600e3).length >= BOOKING_LIMITS.perDay) return { ok: false, status: 429, code: 'busy' };

  const start = new Date(startMs).toISOString();
  const end = new Date(endMs).toISOString();
  const whenHost = `${fmtHost(startMs)} Philippine time`;
  const changeKey = KEY_RE.test(String(key)) ? String(key) : newKey();
  const footer = '\nBooked through the Rework Rescue website.';
  const resultLine = summary ? `\nFind Your Rework result:\n${summary}` : '';

  // Invite: what the visitor sees. No time zone line; Google Calendar already shows their local time.
  const inviteLines = [
    `Name: ${name}`, `Email: ${email}`, company ? `Company: ${company}` : '',
    process ? `Report or process: ${process}` : '', resultLine, footer,
  ].filter(Boolean);

  // Notification: what Jeff sees. Keeps the visitor's time zone.
  const notifyLines = [
    `Name: ${name}`, `Email: ${email}`, company ? `Company: ${company}` : '',
    process ? `Report or process: ${process}` : '', tz ? `Visitor's time zone: ${tz}` : '',
    resultLine, footer,
  ].filter(Boolean);

  return {
    ok: true,
    booking: { name, email, company, process, summary, tz, start, end, key: changeKey },
    event: {
      summary: EVENT_TITLE,
      description: [...INVITE_PREP.slice(0, 2), `${CHANGE_LINE} ${changeLink(changeKey)}`, ...INVITE_PREP.slice(2), ...inviteLines].join('\n'),
      start: { dateTime: start },
      end: { dateTime: end },
      attendees: [{ email, displayName: name }],
      conferenceData: { createRequest: { requestId: `rr-${startMs}-${Math.random().toString(36).slice(2, 10)}`, conferenceSolutionKey: { type: 'hangoutsMeet' } } },
      reminders: { useDefault: true },
      // Private to Jeff's calendar: the change-link key and what the reminders need. Guests never see these.
      extendedProperties: { private: bookingProps({ key: changeKey, name, email, tz, start, nowMs }) },
    },
    notify: {
      subject: `New review booked: ${name}${company ? ` (${company})` : ''}, ${whenHost}`,
      text: [`New free review booked for ${whenHost}.`, '', ...notifyLines, '', 'The calendar invite with the Meet link has been sent to them.'].join('\n'),
    },
  };
}

/**
 * Clear remembered bookings so an email can book again (Jeff's reset link; doesn't touch the calendar or sheet).
 * `email` is one address (any case), or 'all' to clear the whole list.
 * @returns {{history:object[], removed:number}}
 */
function forgetBooking(history, email) {
  const list = history || [];
  const target = String(email ?? '').trim().toLowerCase();
  if (!target) return { history: list, removed: 0 };
  const kept = target === 'all' ? [] : list.filter((h) => h.email !== target);
  return { history: kept, removed: list.length - kept.length };
}

/**
 * Keep the remembered bookings in step after a change: `to` is the new start (ISO), or null when cancelled.
 * Only the entry for that email and old start changes.
 */
function moveBooking(history, { email, from, to }) {
  const target = String(email ?? '').trim().toLowerCase();
  const fromMs = Date.parse(from);
  const same = (h) => h.email === target && Date.parse(h.slot) === fromMs;
  const list = history || [];
  return to ? list.map((h) => (same(h) ? { ...h, slot: to } : h)) : list.filter((h) => !same(h));
}

/** Bookings worth remembering for the limits: drop entries more than a day old whose slot has passed. */
function pruneHistory(history, nowMs) {
  return (history || []).filter((h) => Date.parse(h.slot) > nowMs || nowMs - h.at < 24 * 3600e3);
}

// Google Sheet log: one row per booking. Create a sheet whose first row has exactly these headers.
const SHEET_COLUMNS = [
  'Booked at (PH)', 'Review time (PH)', 'Review time (UTC)', 'Name', 'Email', 'Company',
  'Report or process', 'Visitor time zone', 'Find Your Rework result', 'Meet link', 'Calendar link', 'Status',
];

const fmtSheet = (ms) => new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Asia/Manila', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false,
}).format(new Date(ms)).replace(',', '');

/** The sheet row for a booking that went through. Status starts as "Booked" for Jeff to update by hand. */
function sheetRow(booking, { meet = '', eventLink = '', nowMs = Date.now() } = {}) {
  // A leading = + - @ would make Sheets treat a visitor's text as a formula; prefix those with an apostrophe.
  const safe = (v) => { const s = String(v ?? ''); return /^[=+\-@]/.test(s) ? `'${s}` : s; };
  const values = [
    fmtSheet(nowMs), fmtSheet(Date.parse(booking.start)), booking.start, booking.name, booking.email, booking.company,
    booking.process, booking.tz, booking.summary, meet, eventLink, 'Booked',
  ];
  return Object.fromEntries(SHEET_COLUMNS.map((c, i) => [c, i < 3 ? values[i] : safe(values[i])]));
}

// ---------------------------------------------------------------- Reminder emails to the visitor
// Sent by the workflow 1 day and 1 hour before the review, in the visitor's own time zone.
const SITE_EXAMPLES = 'https://rework-rescue.vercel.app/#samples';

function visitorTime(ms, tz) {
  const opts = { weekday: 'long', month: 'long', day: 'numeric', hour: 'numeric', minute: '2-digit', timeZoneName: 'short' };
  try { return new Intl.DateTimeFormat('en-US', { ...opts, timeZone: tz || 'Asia/Manila' }).format(new Date(ms)); }
  catch { return new Intl.DateTimeFormat('en-US', { ...opts, timeZone: 'Asia/Manila' }).format(new Date(ms)); }
}

/**
 * The reminder emails, in the visitor's own time zone. kind: 'day' (1 day before) or 'hour' (1 hour before).
 * When the booking is sent by src/booking/manage.js (sweepReminders), which decides when each one is due.
 * key: the change-link key; without one (bookings made before 20 Nov) the email says to reply instead.
 */
function reminderEmail(kind, { name = '', email = '', tz = '', start, meet = '', key = '' }) {
  const startMs = Date.parse(start);
  const when = visitorTime(startMs, tz);
  const first = String(name || '').split(' ')[0] || 'there';
  const join = meet ? `Join with Google Meet: ${meet}` : 'The Google Meet link is in your calendar invite.';
  const sign = ['Jeff Herson Vida', 'Rework Rescue · Less rework. More real work.'];
  const link = KEY_RE.test(String(key)) ? changeLink(key) : '';
  if (kind === 'day') {
    return {
      to: email,
      subject: 'Reminder: your free review is tomorrow',
      text: [
        `Hi ${first},`, '',
        'A quick reminder of your free 30-minute review with me tomorrow:', when, join, '',
        `Before the call, have one report, check or workflow in mind that your team keeps redoing, like the examples on my site: ${SITE_EXAMPLES}`,
        'No preparation or files needed, and please leave out anything confidential.', '',
        link ? `${CHANGE_LINE} ${link}` : 'Need to change the time? Just reply to this email.', '', ...sign,
      ].join('\n'),
    };
  }
  return {
    to: email,
    subject: 'Starting in an hour: your free review',
    text: [
      `Hi ${first},`, '', `Your free review starts in an hour: ${when}.`, join, '',
      link ? `Can't make it? Change or cancel here: ${link}` : "Can't make it? Just reply to this email.", '',
      'See you soon,', ...sign,
    ].join('\n'),
  };
}

// ---- workflow step: keep the one-upcoming-review-per-email limit in step (cancelled: the email can book again)
const d = $('Decide the change').first().json;
const store = $getWorkflowStaticData('global');
store.bookings = moveBooking(store.bookings, { email: d.email, from: d.from, to: d.to });
return [{ json: d.respond }];

// Booking slot rules: the ONE place that decides which times can be booked.
//
// Used in two places:
//  - the n8n workflow (copied into its Code nodes by tools/build_n8n.mjs), which checks Google Calendar
//    and returns only the free slots, and re-checks a slot before booking it;
//  - the booking pop-up (src/ui/booking.js), only as a fallback while n8n isn't connected.
//
// Change the hours here, run `node tools/build_n8n.mjs`, and re-import n8n/rework-review-booking.json.
// Keep this file free of imports and browser/Node-only APIs: it must run inside an n8n Code node.

const RULES = {
  hostOffsetHours: 8,          // Philippine time, UTC+8, no daylight saving
  days: [1, 2, 3, 4, 5],       // days a window STARTS on (0 = Sunday): Monday to Friday
  start: '08:00',              // first start time, Philippine time
  end: '02:00',                // window ends at this time; earlier than start means the next day (Fri 8:00 am to Sat 2:00 am)
  slotMinutes: 30,             // meeting length, and the step between start times
  minNoticeHours: 12,          // no bookings sooner than this
  daysAhead: 28,               // how far ahead people can book
};

const MIN = 60e3;

function toMinutes(hhmm) {
  const [h, m] = hhmm.split(':').map(Number);
  return h * 60 + m;
}

/** Every bookable start time (ms since epoch, UTC) from now, before checking the calendar. */
function candidateSlots(nowMs, rules = RULES) {
  const off = rules.hostOffsetHours * 60 * MIN;
  const startMin = toMinutes(rules.start);
  let endMin = toMinutes(rules.end);
  if (endMin <= startMin) endMin += 24 * 60;
  const earliest = nowMs + rules.minNoticeHours * 60 * MIN;
  const latest = nowMs + rules.daysAhead * 24 * 60 * MIN;

  // Host-local midnight of "today", as a UTC timestamp. Start one day back so a window that began
  // yesterday evening and runs past midnight is still included.
  const hostNow = new Date(nowMs + off);
  const todayMidnight = Date.UTC(hostNow.getUTCFullYear(), hostNow.getUTCMonth(), hostNow.getUTCDate()) - off;

  const out = [];
  for (let i = -1; i <= rules.daysAhead + 1; i++) {
    const dayStart = todayMidnight + i * 24 * 60 * MIN;
    const weekday = new Date(dayStart + off).getUTCDay();
    if (!rules.days.includes(weekday)) continue;
    for (let m = startMin; m + rules.slotMinutes <= endMin; m += rules.slotMinutes) {
      const t = dayStart + m * MIN;
      if (t >= earliest && t <= latest) out.push(t);
    }
  }
  return out;
}

/** Free start times: candidates that don't overlap any busy period ({start, end} ISO strings). */
function freeSlots(nowMs, busy = [], rules = RULES) {
  const periods = busy
    .map((b) => [Date.parse(b.start), Date.parse(b.end)])
    .filter(([s, e]) => Number.isFinite(s) && Number.isFinite(e));
  const len = rules.slotMinutes * MIN;
  return candidateSlots(nowMs, rules).filter((t) => !periods.some(([s, e]) => t < e && t + len > s));
}

/** True if this exact start time (ISO string) is one the rules allow. Does not check the calendar. */
function isAllowedSlot(iso, nowMs, rules = RULES) {
  const t = Date.parse(iso);
  if (!Number.isFinite(t)) return false;
  return candidateSlots(nowMs, rules).includes(t);
}

// Change or cancel a booking, and the reminder sweep. Run inside the n8n booking workflow (tools/build_n8n.mjs
// copies this file in with slots.js and check.js; import lines are dropped there). 20 Nov 2026, Jeff: automated.
//
// How it fits together
//  - Every booking's Google Calendar event carries private details (extendedProperties.private, visible only on
//    Jeff's calendar): a random key, the visitor's name, email and time zone, the start the workflow knows about,
//    how many times it was changed, and which reminders went out.
//  - The invite and reminders link to https://rework-rescue.vercel.app/#booking=KEY. The pop-up sends that key to
//    the rr-manage webhook to look the booking up, move it (same event, same Meet link) or cancel it.
//  - Every 10 minutes the workflow reads the calendar and the bookings sheet (sweepReminders): it sends reminders
//    that are due for the event's CURRENT time, notices when Jeff moved or cancelled a review in Google Calendar,
//    or the visitor declined the invite, and keeps the sheet in step.
//
// Keep this file free of browser/Node-only APIs: it must run inside an n8n Code node.

const CHANGE_RULES = {
  maxChanges: 2,            // a visitor can move one booking twice; after that, "reply to the invite"
  // New times follow the normal booking rules in slots.js (12 hours' notice, up to 28 days ahead).
  // Moving or cancelling is possible until the review starts.
};
const SITE_URL = 'https://rework-rescue.vercel.app/';
const EVENT_TITLE = 'Free review with Jeff (Rework Rescue)';
const KEY_RE = /^[A-Za-z0-9]{24,64}$/;
const LIST_DAYS = 60; // how far ahead the sweep reads the calendar (bookings go 28 days ahead)

const HOUR_MS = 3600e3;
const MINUTE_MS = 60e3;

/** The visitor's private link. A #fragment, so the key never reaches a server log or another site. */
const changeLink = (key) => `${SITE_URL}#booking=${key}`;

/** Fallback key if the n8n Crypto node didn't supply one (it normally does). */
function newKey(rand = Math.random) {
  const abc = 'abcdefghijklmnopqrstuvwxyz0123456789';
  let k = '';
  for (let i = 0; i < 32; i++) k += abc[Math.floor(rand() * abc.length) % abc.length];
  return k;
}

/** What a new booking keeps on its calendar event. Google needs every value as a string. */
function bookingProps({ key, name, email, tz, start, nowMs }) {
  return {
    rr: '1', rrKey: key, rrName: name, rrEmail: email, rrTz: tz || '', rrStart: new Date(Date.parse(start)).toISOString(),
    rrSet: String(nowMs), rrChanges: '0', rrDay: '', rrHour: '', rrState: '',
  };
}

const iso = (ms) => new Date(ms).toISOString();
const props = (ev) => ({ ...((ev && ev.extendedProperties && ev.extendedProperties.private) || {}) });
const sheetTimes = (ms) => ({ 'Review time (PH)': fmtSheet(ms), 'Review time (UTC)': iso(ms) });
const host = (ms) => `${fmtHost(ms)} Philippine time`;

// ---------------------------------------------------------------- rr-manage webhook

/**
 * First check of a change request, before Google is asked anything.
 * body: { key, action: 'look' | 'move' | 'cancel', slot? (ISO, for move) }
 */
function checkChange(body, nowMs, rules = RULES) {
  const b = body && typeof body === 'object' ? body : {};
  const key = String(b.key ?? '').trim();
  const action = String(b.action ?? '');
  if (!KEY_RE.test(key)) return { ok: false, status: 404, code: 'not_found' };
  if (!['look', 'move', 'cancel'].includes(action)) return { ok: false, status: 400, code: 'action' };
  if (action !== 'move') return { ok: true, key, action };
  const slot = String(b.slot ?? '').slice(0, 40);
  if (!isAllowedSlot(slot, nowMs, rules)) return { ok: false, status: 400, code: 'slot' };
  const startMs = Date.parse(slot);
  return { ok: true, key, action, start: iso(startMs), end: iso(startMs + rules.slotMinutes * MINUTE_MS) };
}

/**
 * Decide what to do, given the request (checkChange) and Google's answer to
 * events?privateExtendedProperty=rrKey=KEY. Returns what to answer, and for move/cancel what to change.
 */
function decideChange(req, list, nowMs, rules = CHANGE_RULES) {
  const no = (status, code) => ({ ok: false, status, code, respond: { ok: false, error: code } });
  const items = (list && Array.isArray(list.items)) ? list.items : [];
  const ev = items.find((e) => e && e.status !== 'cancelled' && props(e).rrKey === req.key && e.start && e.start.dateTime);
  if (!ev) return no(404, 'not_found');
  const p = props(ev);
  const startMs = Date.parse(ev.start.dateTime);
  const endMs = Date.parse((ev.end && ev.end.dateTime) || '') || startMs + 30 * MINUTE_MS;
  if (!(startMs > nowMs)) return no(410, 'started');
  const changes = Number(p.rrChanges) || 0;
  const left = Math.max(0, rules.maxChanges - changes);
  const name = p.rrName || '';
  const first = name.split(' ')[0] || '';
  const base = { eventId: ev.id, link: ev.htmlLink || '', email: p.rrEmail || '', from: iso(startMs) };

  if (req.action === 'look') {
    return { ok: true, status: 200, action: 'look', respond: { ok: true, start: iso(startMs), end: iso(endMs), name: first, changesLeft: left } };
  }

  const who = [`Name: ${name}`, `Email: ${p.rrEmail || ''}`, p.rrTz ? `Visitor's time zone: ${p.rrTz}` : ''].filter(Boolean);

  if (req.action === 'move') {
    if (left <= 0) return no(409, 'no_changes_left');
    const toMs = Date.parse(req.start);
    if (toMs === startMs) return no(400, 'same_time');
    return {
      ok: true, status: 200, action: 'move', ...base, to: iso(toMs),
      patch: {
        start: { dateTime: req.start }, end: { dateTime: req.end },
        extendedProperties: { private: { ...p, rrStart: iso(toMs), rrSet: String(nowMs), rrChanges: String(changes + 1), rrDay: '', rrHour: '', rrState: '' } },
      },
      sheet: { 'Calendar link': ev.htmlLink || '', ...sheetTimes(toMs), Status: 'Rescheduled' },
      notify: {
        subject: `Review moved: ${name}, now ${host(toMs)}`,
        text: [`${name} moved their free review using the change link.`, '', `From: ${host(startMs)}`, `To:   ${host(toMs)}`, '',
          ...who, '', 'The calendar event and their invite are updated. The Meet link stays the same.',
          `Changes used: ${changes + 1} of ${rules.maxChanges}.`].join('\n'),
      },
      respond: { ok: true, action: 'move', start: iso(toMs), end: req.end, changesLeft: left - 1 },
    };
  }

  // cancel
  return {
    ok: true, status: 200, action: 'cancel', ...base, to: null,
    sheet: { 'Calendar link': ev.htmlLink || '', Status: 'Cancelled' },
    notify: {
      subject: `Review cancelled: ${name}, ${host(startMs)}`,
      text: [`${name} cancelled their free review using the change link.`, '', `Was: ${host(startMs)}`, '', ...who, '',
        'The calendar event is cancelled and Google has told them. Their email can book again.'].join('\n'),
    },
    respond: { ok: true, action: 'cancel' },
  };
}

// ---------------------------------------------------------------- 10-minute sweep: reminders and keeping in step

/** "2026-11-24 09:00" (or with seconds) in Philippine time, as the sheet shows it. */
function parsePh(v) {
  const m = String(v ?? '').match(/(\d{4})-(\d{2})-(\d{2})[ T,]+(\d{1,2}):(\d{2})/);
  if (!m) return NaN;
  return Date.UTC(+m[1], +m[2] - 1, +m[3], +m[4] - 8, +m[5]);
}
function rowStart(row) {
  const utc = String(row['Review time (UTC)'] ?? '');
  if (/Z$|[+-]\d\d:\d\d$/.test(utc) && Number.isFinite(Date.parse(utc))) return Date.parse(utc);
  return parsePh(row['Review time (PH)']);
}

/**
 * @param {object} list   Google events.list for now .. now + LIST_DAYS (singleEvents), ALL events on the calendar
 * @param {object[]} rows the bookings sheet rows (header names as keys)
 * @param {number} nowMs
 * @returns {{items: object[], moves: {email, from, to}[]}}
 *   items: one per thing to do, with any of
 *     eventId + patch  (update the event's private details; done BEFORE the email so a reminder is never sent twice)
 *     email            ({to, subject, text})
 *     sheet            (row update, matched on 'Calendar link')
 *   moves: for the remembered bookings (to = null: cancelled)
 */
function sweepReminders(list, rows, nowMs) {
  if (!list || !Array.isArray(list.items)) throw new Error('Google Calendar list missing: ' + JSON.stringify(list).slice(0, 300));
  const complete = !list.nextPageToken;
  const events = list.items.filter((e) => e && e.status !== 'cancelled');
  const links = new Set(events.map((e) => e.htmlLink).filter(Boolean));
  const rowByLink = new Map((rows || []).filter((r) => r && r['Calendar link']).map((r) => [r['Calendar link'], r]));
  const items = [];
  const moves = [];

  for (const ev of events) {
    let p = props(ev);
    const row = rowByLink.get(ev.htmlLink);
    const tagged = p.rr === '1';
    // Bookings made before 20 Nov have no private details: adopt them from their sheet row (no change link).
    const legacy = !tagged && ev.summary === EVENT_TITLE && !!row;
    if (!tagged && !legacy) continue;
    if (!ev.start || !ev.start.dateTime) continue;
    const startMs = Date.parse(ev.start.dateTime);
    if (!(startMs > nowMs)) continue;
    const start = iso(startMs);
    let changed = false;
    let sheet = null;
    if (legacy) {
      const guest0 = (ev.attendees || []).find((a) => a && !a.organizer && !a.self) || {};
      const bookedAt = parsePh(row['Booked at (PH)']);
      p = {
        rr: '1', rrKey: '', rrName: row.Name || guest0.displayName || '', rrEmail: String(row.Email || guest0.email || '').toLowerCase(),
        rrTz: row['Visitor time zone'] || '', rrStart: start, rrSet: String(Number.isFinite(bookedAt) ? bookedAt : 0),
        rrChanges: '0', rrDay: '', rrHour: '', rrState: '',
      };
      changed = true;
    }

    const guest = (ev.attendees || []).find((a) => a && String(a.email || '').toLowerCase() === p.rrEmail);
    if (guest && guest.responseStatus === 'declined') {
      if (p.rrState !== 'declined') items.push({ eventId: ev.id, patch: { extendedProperties: { private: { ...p, rrState: 'declined' } } }, sheet: { 'Calendar link': ev.htmlLink, Status: 'Declined' } });
      else if (changed) items.push({ eventId: ev.id, patch: { extendedProperties: { private: p } } });
      continue; // no reminders for a declined invite
    }
    if (p.rrState === 'declined') { p.rrState = ''; changed = true; sheet = { 'Calendar link': ev.htmlLink, Status: 'Booked' }; }

    // Moved in Google Calendar (by Jeff, or by a change the sweep hasn't seen): follow the new time.
    if (Date.parse(p.rrStart) !== startMs) {
      moves.push({ email: p.rrEmail, from: p.rrStart, to: start });
      p = { ...p, rrStart: start, rrSet: String(nowMs) };
      changed = true;
      sheet = { 'Calendar link': ev.htmlLink, ...sheetTimes(startMs), Status: 'Rescheduled' };
    }

    // Reminders for the event's current time. The sweep runs every 10 minutes.
    let email = null;
    const ahead = startMs - nowMs;
    const data = { name: p.rrName, email: p.rrEmail, tz: p.rrTz, start, meet: ev.hangoutLink || '', key: p.rrKey };
    if (p.rrHour !== start && ahead <= HOUR_MS && ahead > 10 * MINUTE_MS) {
      email = reminderEmail('hour', data);
      p = { ...p, rrHour: start, rrDay: start };
    } else if (p.rrDay !== start && ahead <= 24 * HOUR_MS && ahead > 2 * HOUR_MS && startMs - (Number(p.rrSet) || 0) >= 24 * HOUR_MS + 5 * MINUTE_MS) {
      // Skipped when the booking (or the last move) was made less than a day ahead, as before.
      email = reminderEmail('day', data);
      p = { ...p, rrDay: start };
    }
    if (email && !p.rrEmail) email = null;
    if (changed || email) items.push({ eventId: ev.id, patch: { extendedProperties: { private: p } }, ...(email ? { email } : {}), ...(sheet ? { sheet } : {}) });
  }

  // Cancelled in Google Calendar: a sheet row still "Booked" or "Rescheduled" whose event is gone.
  // Only when Google's list is complete, so a short or failed read never marks real bookings as cancelled.
  if (complete) {
    for (const row of rows || []) {
      const link = row && row['Calendar link'];
      const t = row ? rowStart(row) : NaN;
      if (!link || !['Booked', 'Rescheduled'].includes(String(row.Status || '').trim())) continue;
      if (!(t > nowMs && t < nowMs + (LIST_DAYS - 1) * 24 * HOUR_MS) || links.has(link)) continue;
      items.push({ sheet: { 'Calendar link': link, Status: 'Cancelled' } });
      moves.push({ email: String(row.Email || '').toLowerCase(), from: iso(t), to: null });
    }
  }
  return { items, moves };
}

// Booking request checks, run inside the n8n workflow before anything touches the calendar.
// The pop-up validates too, but the webhook is public, so these checks are the real gate.
// Copied into n8n by tools/build_n8n.mjs together with slots.js and manage.js (the import lines are dropped there).

const BOOKING_LIMITS = {
  name: 80, email: 254, company: 120, process: 400, summary: 2000, tz: 64,
  perEmailUpcoming: 1,     // one upcoming review per email address
  perDay: 6,               // new bookings accepted in any 24 hours, across everyone
};

// The opening of the calendar invite the visitor receives. Update the link if the site moves to its own domain.
const INVITE_PREP = [
  'Bring one report or check your team keeps redoing. Live example: https://rework-rescue.vercel.app/#samples',
  'No files or prep needed. Please leave out anything confidential.',
  '',
  'Your details',
];

// 20 Nov 2026: each booking gets a private link to change or cancel it (src/booking/manage.js).
const CHANGE_LINE = 'Need a different time? Change or cancel here:';

const clean = (v, max) => String(v ?? '').replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/g, '').replace(/[ \t]+/g, ' ').trim().slice(0, max);
const EMAIL = /^[^\s@<>()[\]\\,;:"]+@[^\s@<>()[\]\\,;:"]+\.[^\s@<>()[\]\\,;:"]{2,}$/;

const fmtHost = (ms) => new Intl.DateTimeFormat('en-US', {
  timeZone: 'Asia/Manila', weekday: 'long', month: 'long', day: 'numeric', hour: 'numeric', minute: '2-digit',
}).format(new Date(ms));

/**
 * @param {object} body     the JSON the pop-up sent
 * @param {number} nowMs
 * @param {{email:string, slot:string, at:number}[]} history  bookings this workflow accepted before
 * @param {object} [rules]
 * @param {string} [key]  the change-link key (from the n8n Crypto node); a fallback key is made if it's missing
 * @returns {{ok:true, booking:object, event:object, notify:object} | {ok:false, status:number, code:string}}
 */
function checkBooking(body, nowMs, history = [], rules = RULES, key = '') {
  const b = body && typeof body === 'object' ? body : {};
  // Honeypot: a hidden field people never fill in. Pretend it worked so bots don't learn anything.
  if (clean(b.website, 200)) return { ok: false, status: 200, code: 'ok' };

  const name = clean(b.name, BOOKING_LIMITS.name + 1);
  const email = clean(b.email, BOOKING_LIMITS.email + 1).toLowerCase();
  const company = clean(b.company, BOOKING_LIMITS.company);
  const process = clean(b.process, BOOKING_LIMITS.process);
  const summary = String(b.summary ?? '').replace(/\r/g, '').trim().slice(0, BOOKING_LIMITS.summary);
  const tz = clean(b.tz, BOOKING_LIMITS.tz);
  const slot = clean(b.slot, 40);

  if (!name || name.length > BOOKING_LIMITS.name) return { ok: false, status: 400, code: 'name' };
  if (!EMAIL.test(email) || email.length > BOOKING_LIMITS.email) return { ok: false, status: 400, code: 'email' };
  if (!isAllowedSlot(slot, nowMs, rules)) return { ok: false, status: 400, code: 'slot' };

  const startMs = Date.parse(slot);
  const endMs = startMs + rules.slotMinutes * 60e3;
  const upcoming = history.filter((h) => h.email === email && Date.parse(h.slot) > nowMs);
  if (upcoming.length >= BOOKING_LIMITS.perEmailUpcoming) return { ok: false, status: 429, code: 'already_booked' };
  if (history.filter((h) => nowMs - h.at < 24 * 3600e3).length >= BOOKING_LIMITS.perDay) return { ok: false, status: 429, code: 'busy' };

  const start = new Date(startMs).toISOString();
  const end = new Date(endMs).toISOString();
  const whenHost = `${fmtHost(startMs)} Philippine time`;
  const changeKey = KEY_RE.test(String(key)) ? String(key) : newKey();
  const footer = '\nBooked through the Rework Rescue website.';
  const resultLine = summary ? `\nFind Your Rework result:\n${summary}` : '';

  // Invite: what the visitor sees. No time zone line; Google Calendar already shows their local time.
  const inviteLines = [
    `Name: ${name}`, `Email: ${email}`, company ? `Company: ${company}` : '',
    process ? `Report or process: ${process}` : '', resultLine, footer,
  ].filter(Boolean);

  // Notification: what Jeff sees. Keeps the visitor's time zone.
  const notifyLines = [
    `Name: ${name}`, `Email: ${email}`, company ? `Company: ${company}` : '',
    process ? `Report or process: ${process}` : '', tz ? `Visitor's time zone: ${tz}` : '',
    resultLine, footer,
  ].filter(Boolean);

  return {
    ok: true,
    booking: { name, email, company, process, summary, tz, start, end, key: changeKey },
    event: {
      summary: EVENT_TITLE,
      description: [...INVITE_PREP.slice(0, 2), `${CHANGE_LINE} ${changeLink(changeKey)}`, ...INVITE_PREP.slice(2), ...inviteLines].join('\n'),
      start: { dateTime: start },
      end: { dateTime: end },
      attendees: [{ email, displayName: name }],
      conferenceData: { createRequest: { requestId: `rr-${startMs}-${Math.random().toString(36).slice(2, 10)}`, conferenceSolutionKey: { type: 'hangoutsMeet' } } },
      reminders: { useDefault: true },
      // Private to Jeff's calendar: the change-link key and what the reminders need. Guests never see these.
      extendedProperties: { private: bookingProps({ key: changeKey, name, email, tz, start, nowMs }) },
    },
    notify: {
      subject: `New review booked: ${name}${company ? ` (${company})` : ''}, ${whenHost}`,
      text: [`New free review booked for ${whenHost}.`, '', ...notifyLines, '', 'The calendar invite with the Meet link has been sent to them.'].join('\n'),
    },
  };
}

/**
 * Clear remembered bookings so an email can book again (Jeff's reset link; doesn't touch the calendar or sheet).
 * `email` is one address (any case), or 'all' to clear the whole list.
 * @returns {{history:object[], removed:number}}
 */
function forgetBooking(history, email) {
  const list = history || [];
  const target = String(email ?? '').trim().toLowerCase();
  if (!target) return { history: list, removed: 0 };
  const kept = target === 'all' ? [] : list.filter((h) => h.email !== target);
  return { history: kept, removed: list.length - kept.length };
}

/**
 * Keep the remembered bookings in step after a change: `to` is the new start (ISO), or null when cancelled.
 * Only the entry for that email and old start changes.
 */
function moveBooking(history, { email, from, to }) {
  const target = String(email ?? '').trim().toLowerCase();
  const fromMs = Date.parse(from);
  const same = (h) => h.email === target && Date.parse(h.slot) === fromMs;
  const list = history || [];
  return to ? list.map((h) => (same(h) ? { ...h, slot: to } : h)) : list.filter((h) => !same(h));
}

/** Bookings worth remembering for the limits: drop entries more than a day old whose slot has passed. */
function pruneHistory(history, nowMs) {
  return (history || []).filter((h) => Date.parse(h.slot) > nowMs || nowMs - h.at < 24 * 3600e3);
}

// Google Sheet log: one row per booking. Create a sheet whose first row has exactly these headers.
const SHEET_COLUMNS = [
  'Booked at (PH)', 'Review time (PH)', 'Review time (UTC)', 'Name', 'Email', 'Company',
  'Report or process', 'Visitor time zone', 'Find Your Rework result', 'Meet link', 'Calendar link', 'Status',
];

const fmtSheet = (ms) => new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Asia/Manila', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false,
}).format(new Date(ms)).replace(',', '');

/** The sheet row for a booking that went through. Status starts as "Booked" for Jeff to update by hand. */
function sheetRow(booking, { meet = '', eventLink = '', nowMs = Date.now() } = {}) {
  // A leading = + - @ would make Sheets treat a visitor's text as a formula; prefix those with an apostrophe.
  const safe = (v) => { const s = String(v ?? ''); return /^[=+\-@]/.test(s) ? `'${s}` : s; };
  const values = [
    fmtSheet(nowMs), fmtSheet(Date.parse(booking.start)), booking.start, booking.name, booking.email, booking.company,
    booking.process, booking.tz, booking.summary, meet, eventLink, 'Booked',
  ];
  return Object.fromEntries(SHEET_COLUMNS.map((c, i) => [c, i < 3 ? values[i] : safe(values[i])]));
}

// ---------------------------------------------------------------- Reminder emails to the visitor
// Sent by the workflow 1 day and 1 hour before the review, in the visitor's own time zone.
const SITE_EXAMPLES = 'https://rework-rescue.vercel.app/#samples';

function visitorTime(ms, tz) {
  const opts = { weekday: 'long', month: 'long', day: 'numeric', hour: 'numeric', minute: '2-digit', timeZoneName: 'short' };
  try { return new Intl.DateTimeFormat('en-US', { ...opts, timeZone: tz || 'Asia/Manila' }).format(new Date(ms)); }
  catch { return new Intl.DateTimeFormat('en-US', { ...opts, timeZone: 'Asia/Manila' }).format(new Date(ms)); }
}

/**
 * The reminder emails, in the visitor's own time zone. kind: 'day' (1 day before) or 'hour' (1 hour before).
 * When the booking is sent by src/booking/manage.js (sweepReminders), which decides when each one is due.
 * key: the change-link key; without one (bookings made before 20 Nov) the email says to reply instead.
 */
function reminderEmail(kind, { name = '', email = '', tz = '', start, meet = '', key = '' }) {
  const startMs = Date.parse(start);
  const when = visitorTime(startMs, tz);
  const first = String(name || '').split(' ')[0] || 'there';
  const join = meet ? `Join with Google Meet: ${meet}` : 'The Google Meet link is in your calendar invite.';
  const sign = ['Jeff Herson Vida', 'Rework Rescue · Less rework. More real work.'];
  const link = KEY_RE.test(String(key)) ? changeLink(key) : '';
  if (kind === 'day') {
    return {
      to: email,
      subject: 'Reminder: your free review is tomorrow',
      text: [
        `Hi ${first},`, '',
        'A quick reminder of your free 30-minute review with me tomorrow:', when, join, '',
        `Before the call, have one report, check or workflow in mind that your team keeps redoing, like the examples on my site: ${SITE_EXAMPLES}`,
        'No preparation or files needed, and please leave out anything confidential.', '',
        link ? `${CHANGE_LINE} ${link}` : 'Need to change the time? Just reply to this email.', '', ...sign,
      ].join('\n'),
    };
  }
  return {
    to: email,
    subject: 'Starting in an hour: your free review',
    text: [
      `Hi ${first},`, '', `Your free review starts in an hour: ${when}.`, join, '',
      link ? `Can't make it? Change or cancel here: ${link}` : "Can't make it? Just reply to this email.", '',
      'See you soon,', ...sign,
    ].join('\n'),
  };
}

// ---- workflow step: reminders due now, and anything moved, cancelled or declined in Google Calendar
const list = $('Google: upcoming events').first().json;
const rows = $input.all().map((i) => i.json).filter((r) => r && r['Calendar link']);
const r = sweepReminders(list, rows, Date.now());
if (r.moves.length) {
